";s:15:\"3px 3px 3px 3px\";s:18:\"logincust_field_bg\";s:7:\"#ffffff\";s:21:\"logincust_field_color\";s:7:\"#333333\";s:19:\"logincust_button_bg\";s:7:\"#198754\";s:25:\"logincust_button_hover_bg\";s:7:\"#0b655e\";s:29:\"logincust_button_height_width\";s:6:\"custom\";s:27:\"logincust_button_width_size\";s:4:\"100%\";s:28:\"logincust_button_height_size\";s:4:\"40px\";s:22:\"logincust_button_color\";s:7:\"#ffffff\";s:24:\"logincust_button_padding\";s:17:\"0px 12px 2px 12px\";s:29:\"logincust_button_border_width\";s:3:\"0px\";s:23:\"logincust_button_shadow\";s:7:\"#0b655e\";s:28:\"logincust_button_text_shadow\";s:7:\"#198754\";s:21:\"logincust_other_color\";s:7:\"#ffffff\";s:27:\"logincust_other_color_hover\";s:7:\"#dddddd\";s:19:\"logincust_other_css\";s:940:\"/* Custom CSS for Material Template */\n#login form#loginform .input,\n#login form#registerform .input,\n#login form#lostpasswordform .input {\n	border-bottom: 1px solid #d2d2d2;\n}\n\n.bar {\n	position: relative;\n	display: block;\n	width: 100%;\n}\n\n.bar:before, .bar:after {\n	content: \"\";\n	height: 2px; \n	width: 0;\n	bottom: 15px; \n	position: absolute;\n	background: #e91e63; \n	transition: all 0.2s ease;\n}\n\n.bar:before { left: 50%; }\n\n.bar:after { right: 50%; }\n\ninput:focus ~ .bar:before, input:focus ~ .bar:after { width: 50%; }\n\n/* custom css by lucas */\ndiv#login {\n	display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n	height: 100%;\n  width: 100%; \n}\ninput#wp-submit { \n	text-shadow: none; \n}\nform#loginform {\n	flex-shrink: 0;\n}\n.login .privacy-policy-page-link {\n	margin-top: 1em;\n}\n.login .language-switcher {\n	margin-top: 3em;\n}\n\n@media screen and (max-width: 480px) {\n	div#login {\n		height: unset;\n	}\n}\";s:18:\"logincust_other_js\";s:374:\"// Custom JS for Material Template\nfunction insertAfter( newNode, referenceNode ) {\n    referenceNode.parentNode.insertBefore( newNode, referenceNode.nextSibling );\n}\n\nvar inputFields = document.querySelectorAll( \".input\" );\n\ninputFields.forEach( ( field ) => {\n	var bar = document.createElement(\"span\");\n		bar.setAttribute( \"class\", \"bar\" );\n	insertAfter( bar, field );\n});\";s:20:\"logincust_logo_width\";s:5:\"120px\";s:21:\"logincust_logo_height\";s:5:\"120px\";s:19:\"logincust_logo_link\";s:24:\"https://bgbh.com.br/blog\";s:21:\"logincust_login_title\";s:12:\"BGBH - Login\";s:26:\"logincust_button_font_size\";s:4:\"14px\";s:25:\"logincust_field_back_blog\";i:1;s:25:\"logincust_other_font_size\";s:4:\"14px\";}', 'yes'),
