ical\":0,\"blur\":0,\"color\":\"rgba(0,0,0,0.3)\"},\"_margin\":{\"unit\":\"px\",\"top\":\"40\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"__globals__\":{\"text_color\":\"globals\\/colors?id=astglobalcolor0\"}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":false}],\"isInner\":false},{\"id\":\"20133bbc\",\"elType\":\"section\",\"settings\":{\"content_width\":{\"unit\":\"px\",\"size\":1340,\"sizes\":[]},\"gap\":\"no\",\"custom_height\":{\"unit\":\"px\",\"size\":1440,\"sizes\":[]},\"structure\":\"20\",\"background_background\":\"classic\",\"padding\":{\"unit\":\"%\",\"top\":\"5\",\"right\":\"5\",\"bottom\":\"5\",\"left\":\"5\",\"isLinked\":false},\"padding_tablet\":{\"unit\":\"%\",\"top\":\"16\",\"right\":\"4\",\"bottom\":\"16\",\"left\":\"4\",\"isLinked\":false},\"padding_mobile\":{\"unit\":\"%\",\"top\":\"26\",\"right\":\"8\",\"bottom\":\"26\",\"left\":\"8\",\"isLinked\":false},\"_element_id\":\"services\",\"_title\":\"Services\",\"__globals__\":{\"background_color\":\"globals\\/colors?id=astglobalcolor5\"}},\"elements\":[{\"id\":\"2b8f7f0f\",\"elType\":\"column\",\"settings\":{\"_column_size\":50,\"_inline_size\":null,\"space_between_widgets\":0,\"padding\":{\"unit\":\"%\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"padding_mobile\":{\"unit\":\"%\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"35\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"934735\",\"elType\":\"widget\",\"settings\":{\"selected_icon\":{\"value\":\"\",\"library\":\"\"},\"title_text\":\"O QUE \\u00c9 UMA MATH TRADE?\",\"description_text\":\"MATH TRADE \\u00e9 um evento voltado para troca de jogos. Uma grande oportunidade para trocar um jogo seu por um jogo de outra pessoa a partir de triangula\\u00e7\\u00f5es geradas por um algoritmo programado para maximizar a quantidade de trocas entre os participantes.\",\"position\":\"left\",\"primary_color\":\"#312A26\",\"icon_space\":{\"unit\":\"px\",\"size\":18,\"siz