(143, 1, '2023-02-09 07:25:02', '2023-02-09 10:25:02', '<!-- wp:cover {\"url\":\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/bgbh-topo-site.jpg\",\"id\":57,\"dimRatio\":0,\"minHeight\":720,\"minHeightUnit\":\"px\",\"customGradient\":\"linear-gradient(35deg,rgb(6,0,151) 0%,rgb(130,4,255) 73%,rgb(193,15,255) 100%)\",\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull\" style=\"min-height:720px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-0 has-background-dim has-background-gradient\" style=\"background:linear-gradient(35deg,rgb(6,0,151) 0%,rgb(130,4,255) 73%,rgb(193,15,255) 100%)\"></span><img class=\"wp-block-cover__image-background wp-image-57\" alt=\"\" src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/bgbh-topo-site.jpg\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":58,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=58\",\"mediaType\":\"image\",\"mediaWidth\":43,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text alignwide has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 43%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"left\",\"level\":1,\"textColor\":\"white\"} -->\n<h1 class=\"has-text-align-left has-white-color has-text-color\">BGBH</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>O seu portal de jogos de tabuleiro</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/bgbh-com-sombra.png\" alt=\"\" class=\"wp-image-58 size-full\"/></figure></div>\n<!-- /wp:media-text --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\"}}},\"backgroundColor\":\"ast-global-color-5\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-ast-global-color-5-background-color has-background\" style=\"padding-bottom:0px\"><!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-top\"><!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"align\":\"center\",\"id\":134,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/building.svg\" alt=\"\" class=\"wp-image-134\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"has-text-align-center\" style=\"margin-top:16px\">Math Trade BH</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Organizamos a maior Math Trade regional do Brasil, a Math Trade BH</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"align\":\"center\",\"id\":135,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/shopping-bag.svg\" alt=\"\" class=\"wp-image-135\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"has-text-align-center\" style=\"margin-top:16px\">Arena de Jogos </h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Estamos presente no maior evento geek de MG, o Nerd Experience</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"align\":\"center\",\"id\":136,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/blog.svg\" alt=\"\" class=\"wp-image-136\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"has-text-align-center\" style=\"margin-top:16px\">Torneios</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Organização de torneios online no BGA</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"align\":\"center\",\"id\":137,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/portfolio.svg\" alt=\"\" class=\"wp-image-137\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"has-text-align-center\" style=\"margin-top:16px\">Grupos de discussão</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Temos diversos grupos no whatsapp para resenha, trocas e vendas e mais</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\",\"top\":\"60px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" id=\"vem-ai\" style=\"padding-top:60px;padding-bottom:0px\"><!-- wp:heading -->\n<h2>NÃO FIQUE DE FORA</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"align\":\"\",\"mediaPosition\":\"right\",\"mediaId\":43,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=43\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"imageFill\":false,\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"}},\"textColor\":\"ast-global-color-4\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center has-ast-global-color-4-color has-text-color has-background\" style=\"background:radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"><div class=\"wp-block-media-text__content\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:80px\"><!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}},\"textColor\":\"ast-global-color-5\"} -->\n<h2 class=\"has-ast-global-color-5-color has-text-color\" style=\"padding-right:40px\">NERD EXPERIENCE 2023</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p class=\"has-ast-global-color-5-color has-text-color\">Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p class=\"has-ast-global-color-5-color has-text-color\">Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div><figure class=\"wp-block-media-text__media\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/326133700_189372070344481_5452170378878663579_n-1024x1024.jpeg\" alt=\"\" class=\"wp-image-43 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:spacer {\"height\":\"60px\"} -->\n<div style=\"height:60px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background\" id=\"vem-ai\" style=\"background:radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%);padding-top:60px;padding-bottom:60px\"><!-- wp:heading {\"textColor\":\"ast-global-color-5\"} -->\n<h2 class=\"has-ast-global-color-5-color has-text-color\">O QUE VEM POR AI?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"align\":\"\",\"mediaId\":59,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=59\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"}}} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center has-background\" style=\"background:radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"><figure class=\"wp-block-media-text__media\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/322515922_5441748755952564_4142625563983561065_n-1024x1024.jpeg\" alt=\"\" class=\"wp-image-59 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:80px\"><!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}}} -->\n<h2 style=\"padding-right:40px\">COVIL CON 2023</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:media-text --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"60px\"} -->\n<div style=\"height:60px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"wide\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\" id=\"aconteceu\"><!-- wp:heading -->\n<h2>O QUE JÁ ACONTECEU</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2>Math Trade Belo Horizonte - Fevereiro 2023</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/o-que-e-uma-math-trade.jpeg\" alt=\"\" class=\"wp-image-40\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"has-text-align-center\" style=\"margin-top:16px\">Explicamos o que é <br>uma Math Trade</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Se não sabe o que é uma Math Trade, nós ajudamos. Temos uma página com explicações básicas do que é e como funciona uma Math Trade.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":41,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/regras-gerais-math-trade.jpeg\" alt=\"\" class=\"wp-image-41\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"has-text-align-center\" style=\"margin-top:16px\">Conheça um pouco <br>mais das regras</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Agora que já sabe o que é, pode dar uma olhada na nossa página de regras gerais para se ambientar e estar pronto a participar de uma Math Trade. </p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":42,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/615x330-MT-Fev23.png\" alt=\"\" class=\"wp-image-42\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"has-text-align-center\" style=\"margin-top:16px\">Math Trade BH <br>5a edição</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">No começo de Fevereiro de 2023 realizamos a 5a edição da Math Trade BH. Como sempre, um sucesso de cadastros e trocas. </p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>NOSSOS TORNEIOS</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":55,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=55\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text alignwide is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/Carcassonne-Banner-Web-1024x347.png\" alt=\"\" class=\"wp-image-55 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Conteúdo...\"} -->\n<p><strong>ENCERRADO</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Em 2022 realizamos etapas regionais de Carcassonne, classificatórias para o nacional. Em 2023 teremos mais novidades</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:paragraph -->\n<p>TORNEIOS REALIZADOS</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:gallery {\"columns\":6,\"linkTo\":\"none\",\"sizeSlug\":\"full\"} -->\n<figure class=\"wp-block-gallery has-nested-images columns-6 is-cropped\"><!-- wp:image {\"id\":56,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-1.png\" alt=\"\" class=\"wp-image-56\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":52,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express.png\" alt=\"\" class=\"wp-image-52\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":47,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne.png\" alt=\"\" class=\"wp-image-47\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel.png\" alt=\"\" class=\"wp-image-51\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":48,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur.png\" alt=\"\" class=\"wp-image-48\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":49,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale.png\" alt=\"\" class=\"wp-image-49\"/></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->\n\n<!-- wp:spacer {\"height\":\"0px\"} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"60px\"} -->\n<div style=\"height:60px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\"},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":false,\"contentSize\":\"800px\",\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group alignfull has-background\" id=\"reviews\" style=\"background:radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"><!-- wp:image {\"align\":\"center\",\"id\":235,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/avatar.png\" alt=\"\" class=\"wp-image-235\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"22px\",\"lineHeight\":1.6}},\"textColor\":\"ast-global-color-5\"} -->\n<p class=\"has-text-align-center has-ast-global-color-5-color has-text-color\" style=\"font-size:22px;line-height:1.6\">“The best part is that Astra comes with hundreds of professionally designed templates for just about every industry, makes it super easy for non-techy users to build a website.”</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"ast-global-color-8\"} -->\n<p class=\"has-text-align-center has-ast-global-color-8-color has-text-color\"><strong>Wade Warren</strong></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}}},\"textColor\":\"ast-global-color-4\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-ast-global-color-4-color has-text-color\" id=\"whyus\" style=\"padding-top:60px;padding-bottom:60px\"><!-- wp:heading -->\n<h2>NOSSOS GRUPOS</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"80px\",\"margin\":{\"top\":\"60px\"}}}} -->\n<div class=\"wp-block-columns\" style=\"margin-top:60px\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":44,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-trocas-vendas.png\" alt=\"\" class=\"wp-image-44\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 style=\"margin-top:1