(445, 1, '2023-03-01 08:46:25', '2023-03-01 11:46:25', '[[[{\"field_key\":\"first_name\",\"general_setting\":{\"label\":\"Nome\",\"description\":\"\",\"field_name\":\"first_name\",\"placeholder\":\"\",\"required\":\"yes\",\"hide_label\":\"no\"},\"advance_setting\":{\"custom_class\":\"\"},\"icon\":\"ur-icon ur-icon-input-first-name\"},{\"field_key\":\"user_email\",\"general_setting\":{\"label\":\"Email\",\"description\":\"\",\"field_name\":\"user_email\",\"placeholder\":\"\",\"required\":\"yes\",\"hide_label\":\"no\"},\"advance_setting\":{\"custom_class\":\"\"},\"icon\":\"ur-icon ur-icon-email\"},{\"field_key\":\"user_login\",\"general_setting\":{\"label\":\"Nome de usuário BGBH\",\"description\":\"\",\"field_name\":\"user_login\",\"placeholder\":\"\",\"required\":\"yes\",\"hide_label\":\"no\"},\"advance_setting\":{\"custom_class\":\"\",\"username_length\":\"\",\"username_character\":\"yes\"},\"icon\":\"ur-icon ur-icon-user\"}],[{\"field_key\":\"last_name\",\"general_setting\":{\"label\":\"Sobrenome\",\"description\":\"\",\"field_name\":\"last_name\",\"placeholder\":\"\",\"required\":\"yes\",\"hide_label\":\"no\"},\"advance_setting\":{\"custom_class\":\"\"},\"icon\":\"ur-icon ur-icon-input-last-name\"},{\"field_key\":\"user_pass\",\"general_setting\":{\"label\":\"Senha\",\"description\":\"Sua senha deve conter no mínimo:\\n- 8 caracteres\\n- Uma letra maiúscula\\n- Uma letra minúscula\\n- Um número\\nRecomendamos que ela tenha também um caracter especial.\",\"field_name\":\"user_pass\",\"placeholder\":\"\",\"required\":\"yes\",\"hide_label\":\"no\"},\"advance_setting\":{\"custom_class\":\"\"},\"icon\":\"ur-icon ur-icon-password\"},{\"general_setting\":{},\"advance_setting\":{}}]],[[{\"field_key\":\"text\",\"general_setting\":{\"label\":\"User BGG\",\"description\":\"\",\"field_name\":\"bgg_user\",\"placeholder\":\"Obrigatório para participar das nossas Math Trades\",\"required\":\"no\",\"hide_label\":\"no\"},\"advance_setting\":{\"size\":\"50\",\"default_value\":\"\"