(515, 1, '2023-12-23 07:46:14', '2023-12-23 10:46:14', '<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\"}}},\"backgroundColor\":\"ast-global-color-5\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-ast-global-color-5-background-color has-background\" style=\"padding-bottom:0px\"><!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-top\"><!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"align\":\"center\",\"id\":134,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/building.svg\" alt=\"\" class=\"wp-image-134\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Math Trade BH</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Organizamos a maior Math Trade regional do Brasil, a Math Trade BH</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"align\":\"center\",\"id\":135,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/shopping-bag.svg\" alt=\"\" class=\"wp-image-135\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Arena de Jogos </h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Estamos presente no maior evento geek de MG, o Nerd Experience</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"align\":\"center\",\"id\":136,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/blog.svg\" alt=\"\" class=\"wp-image-136\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Torneios</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Organização de torneios online no BGA</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"align\":\"center\",\"id\":137,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/portfolio.svg\" alt=\"\" class=\"wp-image-137\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Grupos de discussão</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Temos diversos grupos no whatsapp para resenha, trocas e vendas e mais</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\",\"top\":\"60px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" id=\"vem-ai\" style=\"padding-top:60px;padding-bottom:0px\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">NÃO FIQUE DE FORA</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"align\":\"\",\"mediaPosition\":\"right\",\"mediaId\":43,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=43\",\"linkDestination\":\"custom\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"imageFill\":false,\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"}},\"textColor\":\"ast-global-color-4\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center has-ast-global-color-4-color has-text-color has-background\" style=\"background:radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"><div class=\"wp-block-media-text__content\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:80px\"><!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}},\"textColor\":\"ast-global-color-5\"} -->\n<h2 class=\"wp-block-heading has-ast-global-color-5-color has-text-color\" style=\"padding-right:40px\">NERD EXPERIENCE 2023</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p class=\"has-ast-global-color-5-color has-text-color\">Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p class=\"has-ast-global-color-5-color has-text-color\">Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div><figure class=\"wp-block-media-text__media\"><a href=\"https://nerdexperience.com.br/\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/326133700_189372070344481_5452170378878663579_n-1024x1024.jpeg\" alt=\"\" class=\"wp-image-43 size-full\"/></a></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:spacer {\"height\":\"60px\"} -->\n<div style=\"height:60px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background\" id=\"vem-ai\" style=\"background:radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%);padding-top:60px;padding-bottom:60px\"><!-- wp:heading {\"textColor\":\"ast-global-color-5\"} -->\n<h2 class=\"wp-block-heading has-ast-global-color-5-color has-text-color\">FIQUE LIGADO!</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"align\":\"\",\"mediaId\":59,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=59\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"}}} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center has-background\" style=\"background:radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"><figure class=\"wp-block-media-text__media\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/322515922_5441748755952564_4142625563983561065_n-1024x1024.jpeg\" alt=\"\" class=\"wp-image-59 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:80px\"><!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}}} -->\n<h2 class=\"wp-block-heading\" style=\"padding-right:40px\">COVIL CON 2023</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:media-text --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"60px\"} -->\n<div style=\"height:60px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"wide\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\" id=\"aconteceu\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">O QUE JÁ ACONTECEU</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Math Trade Belo Horizonte - Fevereiro 2023</h3>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/o-que-e-uma-math-trade.jpeg\" alt=\"\" class=\"wp-image-40\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Explicamos o que é <br>uma Math Trade</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Se não sabe o que é uma Math Trade, nós ajudamos. Temos uma página com explicações básicas do que é e como funciona uma Math Trade.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":41,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/regras-gerais-math-trade.jpeg\" alt=\"\" class=\"wp-image-41\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Conheça um pouco <br>mais das regras</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Agora que já sabe o que é, pode dar uma olhada na nossa página de regras gerais para se ambientar e estar pronto a participar de uma Math Trade. </p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":42,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/615x330-MT-Fev23.png\" alt=\"\" class=\"wp-image-42\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Math Trade BH <br>5a edição</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">No começo de Fevereiro de 2023 realizamos a 5a edição da Math Trade BH. Como sempre, um sucesso de cadastros e trocas. </p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">NOSSOS TORNEIOS</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"align\":\"wide\",\"mediaId\":55,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=55\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text alignwide is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/Carcassonne-Banner-Web-1024x347.png\" alt=\"\" class=\"wp-image-55 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Conteúdo...\"} -->\n<p><strong>ENCERRADO</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Em 2022 realizamos etapas regionais de Carcassonne, classificatórias para o nacional. Em 2023 teremos mais novidades</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:paragraph -->\n<p>TORNEIOS REALIZADOS</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:gallery {\"columns\":6,\"linkTo\":\"none\",\"sizeSlug\":\"full\"} -->\n<figure class=\"wp-block-gallery has-nested-images columns-6 is-cropped\"><!-- wp:image {\"id\":56,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-1.png\" alt=\"\" class=\"wp-image-56\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":52,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express.png\" alt=\"\" class=\"wp-image-52\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":47,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne.png\" alt=\"\" class=\"wp-image-47\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel.png\" alt=\"\" class=\"wp-image-51\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":48,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur.png\" alt=\"\" class=\"wp-image-48\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":49,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale.png\" alt=\"\" class=\"wp-image-49\"/></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->\n\n<!-- wp:spacer {\"height\":\"0px\"} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"60px\"} -->\n<div style=\"height:60px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\"},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":false,\"contentSize\":\"800px\",\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group alignfull has-background\" id=\"reviews\" style=\"background:radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"><!-- wp:image {\"align\":\"center\",\"id\":235,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/avatar.png\" alt=\"\" class=\"wp-image-235\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"22px\",\"lineHeight\":1.6}},\"textColor\":\"ast-global-color-5\"} -->\n<p class=\"has-text-align-center has-ast-global-color-5-color has-text-color\" style=\"font-size:22px;line-height:1.6\">“The best part is that Astra comes with hundreds of professionally designed templates for just about every industry, makes it super easy for non-techy users to build a website.”</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"ast-global-color-8\"} -->\n<p class=\"has-text-align-center has-ast-global-color-8-color has-text-color\"><strong>Wade Warren</strong></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}}},\"textColor\":\"ast-global-color-4\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-ast-global-color-4-color has-text-color\" id=\"whyus\" style=\"padding-top:60px;padding-bottom:60px\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">NOSSOS GRUPOS</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"80px\",\"margin\":{\"top\":\"60px\"}}}} -->\n<div class=\"wp-block-columns\" style=\"margin-top:60px\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":44,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-trocas-vendas.png\" alt=\"\" class=\"wp-image-44\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">BGBH - TROCAS &amp; VENDAS</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#404248\">O grupo é&nbsp;<strong>EXCLUSIVO</strong>&nbsp;para Belo Horizonte e Região* e tem como foco os anúncios de trocas e vendas diretamente entre seus usuários. O grupo possui regras bem definidas para otimizar sua funcionalidade.<br><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-ast-global-color-7-color\"><strong>Restrições:&nbsp;Chat moderado.</strong> </mark><em><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-ast-global-color-7-color\"> </mark></em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-center has-small-font-size\"><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-ast-global-color-7-color\">* Participação limitada a usuários que consigam entregar os jogos em Belo Horizonte</mark></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":45,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-resenha.png\" alt=\"\" class=\"wp-image-45\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">BGBH - RESENHA</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#404248\">Grupo voltado para a interação entre amantes de Boardgame. BG é o que nos une mas um bom papo fora do tema não é proibido. Novidades, jogatinas online, presenciais, dúvidas sobre regras, indicações. Aqui é o lugar. A única exigência é o bom senso.<br><br><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-ast-global-color-7-color\"><strong>Restrições:&nbsp;Sem restrições</strong></mark></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":46,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-ofertas.png\" alt=\"\" class=\"wp-image-46\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">BGBH - OFERTAS</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#404248\">Grupo voltado para divulgação de oportunidades e ofertas de Boardgames. Aqui é permitido a divulgação de anúncios em plataformas oficiais além de promoções em luderias e sites. Suas regras e funcionalidade ainda estão sendo definidas.<br><br><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-ast-global-color-7-color\"><strong>Restrições:&nbsp;Sem chat</strong></mark></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%)\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background\" id=\"contact\" style=\"background:radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%);padding-top:40px;padding-bottom:40px\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"medium\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-text-color has-medium-font-size\" style=\"color:#ffffff;font-style:normal;font-weight:400\">ENTRE EM CONTATO CONOSCO E SEJA UM APOIADOR OU PARCEIRO DO NOSSO PROJETO</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->', 'Home', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2023-12-23 07:46:14', '2023-12-23 10:46:14', '', 16, 'https://bgbh.com.br/blog/?p=515', 0, 'revision', '', 0),
(517, 1, '2023-12-23 08:04:17', '2023-12-23 11:04:17', '<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\"}}},\"backgroundColor\":\"ast-global-color-5\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-ast-global-color-5-background-color has-background\" style=\"padding-bottom:0px\"><!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-top\"><!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"align\":\"center\",\"id\":134,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/building.svg\" alt=\"\" class=\"wp-image-134\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Math Trade BH</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Organizamos a maior Math Trade regional do Brasil, a Math Trade BH</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"align\":\"center\",\"id\":135,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/shopping-bag.svg\" alt=\"\" class=\"wp-image-135\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Arena de Jogos </h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Estamos presente no maior evento geek de MG, o Nerd Experience</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"align\":\"center\",\"id\":136,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/blog.svg\" alt=\"\" class=\"wp-image-136\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Torneios</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Organização de torneios online no BGA</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"align\":\"center\",\"id\":137,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/portfolio.svg\" alt=\"\" class=\"wp-image-137\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Grupos de discussão</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Temos diversos grupos no whatsapp para resenha, trocas e vendas e mais</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\",\"top\":\"60px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" id=\"vem-ai\" style=\"padding-top:60px;padding-bottom:0px\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">NÃO FIQUE DE FORA</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"align\":\"\",\"mediaPosition\":\"right\",\"mediaId\":43,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=43\",\"linkDestination\":\"custom\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"imageFill\":false,\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"}},\"textColor\":\"ast-global-color-4\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center has-ast-global-color-4-color has-text-color has-background\" style=\"background:radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"><div class=\"wp-block-media-text__content\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:80px\"><!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}},\"textColor\":\"ast-global-color-5\"} -->\n<h2 class=\"wp-block-heading has-ast-global-color-5-color has-text-color\" style=\"padding-right:40px\">NERD EXPERIENCE 2023</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p class=\"has-ast-global-color-5-color has-text-color\">Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p class=\"has-ast-global-color-5-color has-text-color\">Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div><figure class=\"wp-block-media-text__media\"><a href=\"https://nerdexperience.com.br/\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/326133700_189372070344481_5452170378878663579_n-1024x1024.jpeg\" alt=\"\" class=\"wp-image-43 size-full\"/></a></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:spacer {\"height\":\"60px\"} -->\n<div style=\"height:60px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background\" id=\"vem-ai\" style=\"background:radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%);padding-top:60px;padding-bottom:60px\"><!-- wp:heading {\"textColor\":\"ast-global-color-5\"} -->\n<h2 class=\"wp-block-heading has-ast-global-color-5-color has-text-color\">FIQUE LIGADO!</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"align\":\"\",\"mediaId\":59,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=59\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"}}} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center has-background\" style=\"background:radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"><figure class=\"wp-block-media-text__media\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/322515922_5441748755952564_4142625563983561065_n-1024x1024.jpeg\" alt=\"\" class=\"wp-image-59 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:80px\"><!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}}} -->\n<h2 class=\"wp-block-heading\" style=\"padding-right:40px\">COVIL CON 2023</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:media-text --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"60px\"} -->\n<div style=\"height:60px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"wide\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\" id=\"aconteceu\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">O QUE JÁ ACONTECEU</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Math Trade Belo Horizonte - Fevereiro 2023</h3>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/o-que-e-uma-math-trade.jpeg\" alt=\"\" class=\"wp-image-40\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Explicamos o que é <br>uma Math Trade</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Se não sabe o que é uma Math Trade, nós ajudamos. Temos uma página com explicações básicas do que é e como funciona uma Math Trade.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":41,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/regras-gerais-math-trade.jpeg\" alt=\"\" class=\"wp-image-41\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Conheça um pouco <br>mais das regras</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Agora que já sabe o que é, pode dar uma olhada na nossa página de regras gerais para se ambientar e estar pronto a participar de uma Math Trade. </p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":42,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/615x330-MT-Fev23.png\" alt=\"\" class=\"wp-image-42\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Math Trade BH <br>5a edição</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">No começo de Fevereiro de 2023 realizamos a 5a edição da Math Trade BH. Como sempre, um sucesso de cadastros e trocas. </p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">NOSSOS TORNEIOS</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"align\":\"wide\",\"mediaId\":55,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=55\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text alignwide is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/Carcassonne-Banner-Web-1024x347.png\" alt=\"\" class=\"wp-image-55 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Conteúdo...\"} -->\n<p><strong>ENCERRADO</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Em 2022 realizamos etapas regionais de Carcassonne, classificatórias para o nacional. Em 2023 teremos mais novidades</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:paragraph -->\n<p>TORNEIOS REALIZADOS</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:gallery {\"columns\":6,\"linkTo\":\"none\",\"sizeSlug\":\"full\"} -->\n<figure class=\"wp-block-gallery has-nested-images columns-6 is-cropped\"><!-- wp:image {\"id\":56,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-1.png\" alt=\"\" class=\"wp-image-56\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":52,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express.png\" alt=\"\" class=\"wp-image-52\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":47,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne.png\" alt=\"\" class=\"wp-image-47\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel.png\" alt=\"\" class=\"wp-image-51\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":48,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur.png\" alt=\"\" class=\"wp-image-48\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":49,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale.png\" alt=\"\" class=\"wp-image-49\"/></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->\n\n<!-- wp:spacer {\"height\":\"0px\"} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"60px\"} -->\n<div style=\"height:60px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\"},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":false,\"contentSize\":\"800px\",\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group alignfull has-background\" id=\"reviews\" style=\"background:radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"><!-- wp:image {\"align\":\"center\",\"id\":235,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/avatar.png\" alt=\"\" class=\"wp-image-235\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"22px\",\"lineHeight\":1.6}},\"textColor\":\"ast-global-color-5\"} -->\n<p class=\"has-text-align-center has-ast-global-color-5-color has-text-color\" style=\"font-size:22px;line-height:1.6\">“The best part is that Astra comes with hundreds of professionally designed templates for just about every industry, makes it super easy for non-techy users to build a website.”</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"ast-global-color-8\"} -->\n<p class=\"has-text-align-center has-ast-global-color-8-color has-text-color\"><strong>Wade Warren</strong></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}}},\"textColor\":\"ast-global-color-4\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-ast-global-color-4-color has-text-color\" id=\"whyus\" style=\"padding-top:60px;padding-bottom:60px\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">NOSSOS GRUPOS</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"80px\",\"margin\":{\"top\":\"60px\"}}}} -->\n<div class=\"wp-block-columns\" style=\"margin-top:60px\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":44,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-trocas-vendas.png\" alt=\"\" class=\"wp-image-44\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">BGBH - TROCAS &amp; VENDAS</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#404248\">O grupo é&nbsp;<strong>EXCLUSIVO</strong>&nbsp;para Belo Horizonte e Região* e tem como foco os anúncios de trocas e vendas diretamente entre seus usuários. O grupo possui regras bem definidas para otimizar sua funcionalidade.<br><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-ast-global-color-7-color\"><strong>Restrições:&nbsp;Chat moderado.</strong> </mark><em><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-ast-global-color-7-color\"> </mark></em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-center has-small-font-size\"><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-ast-global-color-7-color\">* Participação limitada a usuários que consigam entregar os jogos em Belo Horizonte</mark></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":45,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-resenha.png\" alt=\"\" class=\"wp-image-45\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">BGBH - RESENHA</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#404248\">Grupo voltado para a interação entre amantes de Boardgame. BG é o que nos une mas um bom papo fora do tema não é proibido. Novidades, jogatinas online, presenciais, dúvidas sobre regras, indicações. Aqui é o lugar. A única exigência é o bom senso.<br><br><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-ast-global-color-7-color\"><strong>Restrições:&nbsp;Sem restrições</strong></mark></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":46,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-ofertas.png\" alt=\"\" class=\"wp-image-46\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">BGBH - OFERTAS</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#404248\">Grupo voltado para divulgação de oportunidades e ofertas de Boardgames. Aqui é permitido a divulgação de anúncios em plataformas oficiais além de promoções em luderias e sites. Suas regras e funcionalidade ainda estão sendo definidas.<br><br><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-ast-global-color-7-color\"><strong>Restrições:&nbsp;Sem chat</strong></mark></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%)\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background\" id=\"contact\" style=\"background:radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%);padding-top:40px;padding-bottom:40px\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"medium\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-text-color has-medium-font-size\" style=\"color:#ffffff;font-style:normal;font-weight:400\">ENTRE EM CONTATO CONOSCO E SEJA UM APOIADOR OU PARCEIRO DO NOSSO PROJETO</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->', 'Home', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2023-12-23 08:04:17', '2023-12-23 11:04:17', '', 16, 'https://bgbh.com.br/blog/?p=517', 0, 'revision', '', 0);
INSERT INTO `wptask_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(518, 1, '2023-12-23 08:04:18', '2023-12-23 11:04:18', '<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\"}}},\"backgroundColor\":\"ast-global-color-5\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-ast-global-color-5-background-color has-background\" style=\"padding-bottom:0px\"><!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-top\"><!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"align\":\"center\",\"id\":134,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/building.svg\" alt=\"\" class=\"wp-image-134\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Math Trade BH</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Organizamos a maior Math Trade regional do Brasil, a Math Trade BH</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"align\":\"center\",\"id\":135,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/shopping-bag.svg\" alt=\"\" class=\"wp-image-135\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Arena de Jogos </h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Estamos presente no maior evento geek de MG, o Nerd Experience</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"align\":\"center\",\"id\":136,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/blog.svg\" alt=\"\" class=\"wp-image-136\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Torneios</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Organização de torneios online no BGA</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"align\":\"center\",\"id\":137,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/portfolio.svg\" alt=\"\" class=\"wp-image-137\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Grupos de discussão</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Temos diversos grupos no whatsapp para resenha, trocas e vendas e mais</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\",\"top\":\"60px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" id=\"vem-ai\" style=\"padding-top:60px;padding-bottom:0px\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">NÃO FIQUE DE FORA</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"align\":\"\",\"mediaPosition\":\"right\",\"mediaId\":43,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=43\",\"linkDestination\":\"custom\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"imageFill\":false,\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"}},\"textColor\":\"ast-global-color-4\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center has-ast-global-color-4-color has-text-color has-background\" style=\"background:radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"><div class=\"wp-block-media-text__content\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:80px\"><!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}},\"textColor\":\"ast-global-color-5\"} -->\n<h2 class=\"wp-block-heading has-ast-global-color-5-color has-text-color\" style=\"padding-right:40px\">NERD EXPERIENCE 2023</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p class=\"has-ast-global-color-5-color has-text-color\">Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p class=\"has-ast-global-color-5-color has-text-color\">Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div><figure class=\"wp-block-media-text__media\"><a href=\"https://nerdexperience.com.br/\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/326133700_189372070344481_5452170378878663579_n-1024x1024.jpeg\" alt=\"\" class=\"wp-image-43 size-full\"/></a></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:spacer {\"height\":\"60px\"} -->\n<div style=\"height:60px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background\" id=\"vem-ai\" style=\"background:radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%);padding-top:60px;padding-bottom:60px\"><!-- wp:heading {\"textColor\":\"ast-global-color-5\"} -->\n<h2 class=\"wp-block-heading has-ast-global-color-5-color has-text-color\">FIQUE LIGADO!</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"align\":\"\",\"mediaId\":59,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=59\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"}}} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center has-background\" style=\"background:radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"><figure class=\"wp-block-media-text__media\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/322515922_5441748755952564_4142625563983561065_n-1024x1024.jpeg\" alt=\"\" class=\"wp-image-59 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:80px\"><!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}}} -->\n<h2 class=\"wp-block-heading\" style=\"padding-right:40px\">COVIL CON 2023</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:media-text --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"60px\"} -->\n<div style=\"height:60px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"wide\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\" id=\"aconteceu\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">O QUE JÁ ACONTECEU</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Math Trade Belo Horizonte - Fevereiro 2023</h3>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/o-que-e-uma-math-trade.jpeg\" alt=\"\" class=\"wp-image-40\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Explicamos o que é <br>uma Math Trade</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Se não sabe o que é uma Math Trade, nós ajudamos. Temos uma página com explicações básicas do que é e como funciona uma Math Trade.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":41,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/regras-gerais-math-trade.jpeg\" alt=\"\" class=\"wp-image-41\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Conheça um pouco <br>mais das regras</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Agora que já sabe o que é, pode dar uma olhada na nossa página de regras gerais para se ambientar e estar pronto a participar de uma Math Trade. </p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":42,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/615x330-MT-Fev23.png\" alt=\"\" class=\"wp-image-42\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">Math Trade BH <br>5a edição</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">No começo de Fevereiro de 2023 realizamos a 5a edição da Math Trade BH. Como sempre, um sucesso de cadastros e trocas. </p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">NOSSOS TORNEIOS</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"align\":\"wide\",\"mediaId\":55,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=55\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text alignwide is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/Carcassonne-Banner-Web-1024x347.png\" alt=\"\" class=\"wp-image-55 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Conteúdo...\"} -->\n<p><strong>ENCERRADO</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Em 2022 realizamos etapas regionais de Carcassonne, classificatórias para o nacional. Em 2023 teremos mais novidades</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:paragraph -->\n<p>TORNEIOS REALIZADOS</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:gallery {\"columns\":6,\"linkTo\":\"none\",\"sizeSlug\":\"full\"} -->\n<figure class=\"wp-block-gallery has-nested-images columns-6 is-cropped\"><!-- wp:image {\"id\":56,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-1.png\" alt=\"\" class=\"wp-image-56\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":52,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express.png\" alt=\"\" class=\"wp-image-52\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":47,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne.png\" alt=\"\" class=\"wp-image-47\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel.png\" alt=\"\" class=\"wp-image-51\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":48,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur.png\" alt=\"\" class=\"wp-image-48\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":49,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale.png\" alt=\"\" class=\"wp-image-49\"/></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->\n\n<!-- wp:spacer {\"height\":\"0px\"} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"60px\"} -->\n<div style=\"height:60px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\"},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":false,\"contentSize\":\"800px\",\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group alignfull has-background\" id=\"reviews\" style=\"background:radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"><!-- wp:image {\"align\":\"center\",\"id\":235,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image aligncenter size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/avatar.png\" alt=\"\" class=\"wp-image-235\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"22px\",\"lineHeight\":1.6}},\"textColor\":\"ast-global-color-5\"} -->\n<p class=\"has-text-align-center has-ast-global-color-5-color has-text-color\" style=\"font-size:22px;line-height:1.6\">“The best part is that Astra comes with hundreds of professionally designed templates for just about every industry, makes it super easy for non-techy users to build a website.”</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"ast-global-color-8\"} -->\n<p class=\"has-text-align-center has-ast-global-color-8-color has-text-color\"><strong>Wade Warren</strong></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}}},\"textColor\":\"ast-global-color-4\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-ast-global-color-4-color has-text-color\" id=\"whyus\" style=\"padding-top:60px;padding-bottom:60px\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">NOSSOS GRUPOS</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"80px\",\"margin\":{\"top\":\"60px\"}}}} -->\n<div class=\"wp-block-columns\" style=\"margin-top:60px\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":44,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-trocas-vendas.png\" alt=\"\" class=\"wp-image-44\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">BGBH - TROCAS &amp; VENDAS</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#404248\">O grupo é&nbsp;<strong>EXCLUSIVO</strong>&nbsp;para Belo Horizonte e Região* e tem como foco os anúncios de trocas e vendas diretamente entre seus usuários. O grupo possui regras bem definidas para otimizar sua funcionalidade.<br><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-ast-global-color-7-color\"><strong>Restrições:&nbsp;Chat moderado.</strong> </mark><em><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-ast-global-color-7-color\"> </mark></em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-center has-small-font-size\"><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-ast-global-color-7-color\">* Participação limitada a usuários que consigam entregar os jogos em Belo Horizonte</mark></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":45,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-resenha.png\" alt=\"\" class=\"wp-image-45\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">BGBH - RESENHA</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#404248\">Grupo voltado para a interação entre amantes de Boardgame. BG é o que nos une mas um bom papo fora do tema não é proibido. Novidades, jogatinas online, presenciais, dúvidas sobre regras, indicações. Aqui é o lugar. A única exigência é o bom senso.<br><br><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-ast-global-color-7-color\"><strong>Restrições:&nbsp;Sem restrições</strong></mark></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":46,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-ofertas.png\" alt=\"\" class=\"wp-image-46\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:16px\">BGBH - OFERTAS</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#404248\">Grupo voltado para divulgação de oportunidades e ofertas de Boardgames. Aqui é permitido a divulgação de anúncios em plataformas oficiais além de promoções em luderias e sites. Suas regras e funcionalidade ainda estão sendo definidas.<br><br><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-ast-global-color-7-color\"><strong>Restrições:&nbsp;Sem chat</strong></mark></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%)\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background\" id=\"contact\" style=\"background:radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%);padding-top:40px;padding-bottom:40px\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"medium\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-text-color has-medium-font-size\" style=\"color:#ffffff;font-style:normal;font-weight:400\">ENTRE EM CONTATO CONOSCO E SEJA UM APOIADOR OU PARCEIRO DO NOSSO PROJETO</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->', 'Home', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2023-12-23 08:04:18', '2023-12-23 11:04:18', '', 16, 'https://bgbh.com.br/blog/?p=518', 0, 'revision', '', 0),
(519, 1, '2023-12-23 08:04:18', '2023-12-23 11:04:18', '<link rel=\"stylesheet\" href=\"https://bgbh.com.br/blog/wp-content/plugins/elementor/assets/css/widget-icon-box.min.css\">		\n				<h3>\n						MATH TRADE BH					\n				</h3>\n									<p>\n						Organizamos a maior Math Trade regional do Brasil, a Math Trade BH					</p>\n				<h3>\n						Arena de Jogos					\n				</h3>\n									<p>\n						Estamos presente no maior evento geek de MG, o Nerd Experience, além de outros eventos Geek					</p>\n				<h3>\n						Grupos de discussão					\n				</h3>\n									<p>\n						Através da nossa \"Sala de Embarque\" tenha acesso a diversos grupos para interagir com a comunidade					</p>\n		<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\"}}},\"backgroundColor\":\"ast-global-color-5\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}}} -->\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":134,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<h2>NÃO FIQUE DE FORA</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaPosition\":\"right\",\"mediaId\":43,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=43\",\"linkDestination\":\"custom\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"imageFill\":false,\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"}},\"textColor\":\"ast-global-color-4\"} -->\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}},\"textColor\":\"ast-global-color-5\"} -->\n<h2 style=\"padding-right: 40px;\">NERD EXPERIENCE 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<figure><a href=\"https://nerdexperience.com.br/\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/326133700_189372070344481_5452170378878663579_n-1024x1024.jpeg\" alt=\"\" /></a></figure>\n<!-- /wp:media-text --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textColor\":\"ast-global-color-5\"} -->\n<h2>FIQUE LIGADO!</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaId\":59,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=59\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"}}} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/322515922_5441748755952564_4142625563983561065_n-1024x1024.jpeg\" alt=\"\" /></figure>\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}}} -->\n<h2 style=\"padding-right: 40px;\">COVIL CON 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<!-- /wp:media-text -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"wide\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>O QUE JÁ ACONTECEU</h2>\n<!-- /wp:heading --><!-- wp:heading {\"level\":3} -->\n<h3>Math Trade Belo Horizonte - Fevereiro 2023</h3>\n<!-- /wp:heading --><!-- wp:columns -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/o-que-e-uma-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Explicamos o que é <br />uma Math Trade</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Se não sabe o que é uma Math Trade, nós ajudamos. Temos uma página com explicações básicas do que é e como funciona uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":41,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/regras-gerais-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Conheça um pouco <br />mais das regras</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Agora que já sabe o que é, pode dar uma olhada na nossa página de regras gerais para se ambientar e estar pronto a participar de uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/615x330-MT-Fev23.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Math Trade BH <br />5a edição</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>No começo de Fevereiro de 2023 realizamos a 5a edição da Math Trade BH. Como sempre, um sucesso de cadastros e trocas.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns --><!-- wp:spacer {\"height\":\"40px\"} -->\n \n<!-- /wp:spacer --><!-- wp:heading {\"level\":3} -->\n<h3>NOSSOS TORNEIOS</h3>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"wide\",\"mediaId\":55,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=55\",\"mediaType\":\"image\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/Carcassonne-Banner-Web-1024x347.png\" alt=\"\" /></figure>\n<!-- wp:paragraph {\"placeholder\":\"Conteúdo...\"} -->\n<p><strong>ENCERRADO</strong></p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Em 2022 realizamos etapas regionais de Carcassonne, classificatórias para o nacional. Em 2023 teremos mais novidades</p>\n<!-- /wp:paragraph -->\n<!-- /wp:media-text --><!-- wp:paragraph -->\n<p>TORNEIOS REALIZADOS</p>\n<!-- /wp:paragraph --><!-- wp:gallery {\"columns\":6,\"linkTo\":\"none\",\"sizeSlug\":\"full\"} -->\n<figure><!-- wp:image {\"id\":56,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-1.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":52,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":47,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":48,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":49,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale.png\" alt=\"\" /></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery --><!-- wp:spacer {\"height\":\"0px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\"},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":false,\"contentSize\":\"800px\",\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":235,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/avatar.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"22px\",\"lineHeight\":1.6}},\"textColor\":\"ast-global-color-5\"} -->\n<p style=\"font-size: 22px; line-height: 1.6;\">“The best part is that Astra comes with hundreds of professionally designed templates for just about every industry, makes it super easy for non-techy users to build a website.”</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"ast-global-color-8\"} -->\n<p><strong>Wade Warren</strong></p>\n<!-- /wp:paragraph -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}}},\"textColor\":\"ast-global-color-4\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>NOSSOS GRUPOS</h2>\n<!-- /wp:heading --><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"80px\",\"margin\":{\"top\":\"60px\"}}}} -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":44,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-trocas-vendas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - TROCAS &amp; VENDAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">O grupo é <strong>EXCLUSIVO</strong> para Belo Horizonte e Região* e tem como foco os anúncios de trocas e vendas diretamente entre seus usuários. O grupo possui regras bem definidas para otimizar sua funcionalidade.<br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Chat moderado.</strong> </mark><mark style=\"background-color: rgba(0, 0, 0, 0);\"> </mark></p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p><mark style=\"background-color: rgba(0, 0, 0, 0);\">* Participação limitada a usuários que consigam entregar os jogos em Belo Horizonte</mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":45,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-resenha.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - RESENHA</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para a interação entre amantes de Boardgame. BG é o que nos une mas um bom papo fora do tema não é proibido. Novidades, jogatinas online, presenciais, dúvidas sobre regras, indicações. Aqui é o lugar. A única exigência é o bom senso.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem restrições</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":46,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-ofertas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - OFERTAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para divulgação de oportunidades e ofertas de Boardgames. Aqui é permitido a divulgação de anúncios em plataformas oficiais além de promoções em luderias e sites. Suas regras e funcionalidade ainda estão sendo definidas.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem chat</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%)\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"medium\"} -->\n<h2 style=\"color: #ffffff; font-style: normal; font-weight: 400;\">ENTRE EM CONTATO CONOSCO E SEJA UM APOIADOR OU PARCEIRO DO NOSSO PROJETO</h2>\n<!-- /wp:heading -->\n<!-- /wp:group -->		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>TORNEIOS REALIZADOS</h2>		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-widget-image-carousel .swiper,.elementor-widget-image-carousel .swiper-container{position:static}.elementor-widget-image-carousel .swiper-container .swiper-slide figure,.elementor-widget-image-carousel .swiper .swiper-slide figure{line-height:inherit}.elementor-widget-image-carousel .swiper-slide{text-align:center}.elementor-image-carousel-wrapper:not(.swiper-container-initialized):not(.swiper-initialized) .swiper-slide{max-width:calc(100% / var(--e-image-carousel-slides-to-show, 3))}</style>		\n								<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne-300x161.png\" alt=\"torneio-carcassonne\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-300x161.png\" alt=\"torneio-draftosaurus\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel-300x161.png\" alt=\"torneio-7wduel\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express-300x161.png\" alt=\"torneio-colt-express\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur-300x161.png\" alt=\"torneio-jaipur\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale-300x161.png\" alt=\"torneio-forsale\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/desafio-sushigo-300x161.png\" alt=\"desafio-sushigo\" /></figure>', 'Home', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2023-12-23 08:04:18', '2023-12-23 11:04:18', '', 16, 'https://bgbh.com.br/blog/?p=519', 0, 'revision', '', 0);
INSERT INTO `wptask_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(520, 1, '2023-12-23 08:04:38', '2023-12-23 11:04:38', '<link rel=\"stylesheet\" href=\"https://bgbh.com.br/blog/wp-content/plugins/elementor/assets/css/widget-icon-box.min.css\">		\n				<h3>\n						MATH TRADE BH					\n				</h3>\n									<p>\n						Organizamos a maior Math Trade regional do Brasil, a Math Trade BH					</p>\n				<h3>\n						Arena de Jogos					\n				</h3>\n									<p>\n						Estamos presente no maior evento geek de MG, o Nerd Experience, além de outros eventos Geek					</p>\n				<h3>\n						Grupos de discussão					\n				</h3>\n									<p>\n						Através da nossa \"Sala de Embarque\" tenha acesso a diversos grupos para interagir com a comunidade					</p>\n		<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\"}}},\"backgroundColor\":\"ast-global-color-5\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}}} -->\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":134,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<h2>NÃO FIQUE DE FORA</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaPosition\":\"right\",\"mediaId\":43,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=43\",\"linkDestination\":\"custom\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"imageFill\":false,\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"}},\"textColor\":\"ast-global-color-4\"} -->\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}},\"textColor\":\"ast-global-color-5\"} -->\n<h2 style=\"padding-right: 40px;\">NERD EXPERIENCE 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<figure><a href=\"https://nerdexperience.com.br/\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/326133700_189372070344481_5452170378878663579_n-1024x1024.jpeg\" alt=\"\" /></a></figure>\n<!-- /wp:media-text --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textColor\":\"ast-global-color-5\"} -->\n<h2>FIQUE LIGADO!</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaId\":59,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=59\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"}}} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/322515922_5441748755952564_4142625563983561065_n-1024x1024.jpeg\" alt=\"\" /></figure>\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}}} -->\n<h2 style=\"padding-right: 40px;\">COVIL CON 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<!-- /wp:media-text -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"wide\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>O QUE JÁ ACONTECEU</h2>\n<!-- /wp:heading --><!-- wp:heading {\"level\":3} -->\n<h3>Math Trade Belo Horizonte - Fevereiro 2023</h3>\n<!-- /wp:heading --><!-- wp:columns -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/o-que-e-uma-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Explicamos o que é <br />uma Math Trade</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Se não sabe o que é uma Math Trade, nós ajudamos. Temos uma página com explicações básicas do que é e como funciona uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":41,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/regras-gerais-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Conheça um pouco <br />mais das regras</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Agora que já sabe o que é, pode dar uma olhada na nossa página de regras gerais para se ambientar e estar pronto a participar de uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/615x330-MT-Fev23.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Math Trade BH <br />5a edição</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>No começo de Fevereiro de 2023 realizamos a 5a edição da Math Trade BH. Como sempre, um sucesso de cadastros e trocas.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns --><!-- wp:spacer {\"height\":\"40px\"} -->\n \n<!-- /wp:spacer --><!-- wp:heading {\"level\":3} -->\n<h3>NOSSOS TORNEIOS</h3>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"wide\",\"mediaId\":55,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=55\",\"mediaType\":\"image\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/Carcassonne-Banner-Web-1024x347.png\" alt=\"\" /></figure>\n<!-- wp:paragraph {\"placeholder\":\"Conteúdo...\"} -->\n<p><strong>ENCERRADO</strong></p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Em 2022 realizamos etapas regionais de Carcassonne, classificatórias para o nacional. Em 2023 teremos mais novidades</p>\n<!-- /wp:paragraph -->\n<!-- /wp:media-text --><!-- wp:paragraph -->\n<p>TORNEIOS REALIZADOS</p>\n<!-- /wp:paragraph --><!-- wp:gallery {\"columns\":6,\"linkTo\":\"none\",\"sizeSlug\":\"full\"} -->\n<figure><!-- wp:image {\"id\":56,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-1.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":52,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":47,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":48,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":49,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale.png\" alt=\"\" /></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery --><!-- wp:spacer {\"height\":\"0px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\"},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":false,\"contentSize\":\"800px\",\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":235,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/avatar.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"22px\",\"lineHeight\":1.6}},\"textColor\":\"ast-global-color-5\"} -->\n<p style=\"font-size: 22px; line-height: 1.6;\">“The best part is that Astra comes with hundreds of professionally designed templates for just about every industry, makes it super easy for non-techy users to build a website.”</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"ast-global-color-8\"} -->\n<p><strong>Wade Warren</strong></p>\n<!-- /wp:paragraph -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}}},\"textColor\":\"ast-global-color-4\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>NOSSOS GRUPOS</h2>\n<!-- /wp:heading --><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"80px\",\"margin\":{\"top\":\"60px\"}}}} -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":44,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-trocas-vendas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - TROCAS &amp; VENDAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">O grupo é <strong>EXCLUSIVO</strong> para Belo Horizonte e Região* e tem como foco os anúncios de trocas e vendas diretamente entre seus usuários. O grupo possui regras bem definidas para otimizar sua funcionalidade.<br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Chat moderado.</strong> </mark><mark style=\"background-color: rgba(0, 0, 0, 0);\"> </mark></p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p><mark style=\"background-color: rgba(0, 0, 0, 0);\">* Participação limitada a usuários que consigam entregar os jogos em Belo Horizonte</mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":45,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-resenha.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - RESENHA</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para a interação entre amantes de Boardgame. BG é o que nos une mas um bom papo fora do tema não é proibido. Novidades, jogatinas online, presenciais, dúvidas sobre regras, indicações. Aqui é o lugar. A única exigência é o bom senso.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem restrições</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":46,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-ofertas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - OFERTAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para divulgação de oportunidades e ofertas de Boardgames. Aqui é permitido a divulgação de anúncios em plataformas oficiais além de promoções em luderias e sites. Suas regras e funcionalidade ainda estão sendo definidas.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem chat</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%)\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"medium\"} -->\n<h2 style=\"color: #ffffff; font-style: normal; font-weight: 400;\">ENTRE EM CONTATO CONOSCO E SEJA UM APOIADOR OU PARCEIRO DO NOSSO PROJETO</h2>\n<!-- /wp:heading -->\n<!-- /wp:group -->		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>TORNEIOS REALIZADOS</h2>		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-widget-image-carousel .swiper,.elementor-widget-image-carousel .swiper-container{position:static}.elementor-widget-image-carousel .swiper-container .swiper-slide figure,.elementor-widget-image-carousel .swiper .swiper-slide figure{line-height:inherit}.elementor-widget-image-carousel .swiper-slide{text-align:center}.elementor-image-carousel-wrapper:not(.swiper-container-initialized):not(.swiper-initialized) .swiper-slide{max-width:calc(100% / var(--e-image-carousel-slides-to-show, 3))}</style>		\n								<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne-300x161.png\" alt=\"torneio-carcassonne\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-300x161.png\" alt=\"torneio-draftosaurus\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel-300x161.png\" alt=\"torneio-7wduel\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express-300x161.png\" alt=\"torneio-colt-express\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur-300x161.png\" alt=\"torneio-jaipur\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale-300x161.png\" alt=\"torneio-forsale\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/desafio-sushigo-300x161.png\" alt=\"desafio-sushigo\" /></figure>', 'Home', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2023-12-23 08:04:38', '2023-12-23 11:04:38', '', 16, 'https://bgbh.com.br/blog/?p=520', 0, 'revision', '', 0),
(521, 1, '2023-12-23 08:04:38', '2023-12-23 11:04:38', '<link rel=\"stylesheet\" href=\"https://bgbh.com.br/blog/wp-content/plugins/elementor/assets/css/widget-icon-box.min.css\">		\n				<h3>\n						MATH TRADE BH					\n				</h3>\n									<p>\n						Organizamos a maior Math Trade regional do Brasil, a Math Trade BH					</p>\n				<h3>\n						Arena de Jogos					\n				</h3>\n									<p>\n						Estamos presente no maior evento geek de MG, o Nerd Experience, além de outros eventos Geek					</p>\n				<h3>\n						Grupos de discussão					\n				</h3>\n									<p>\n						Através da nossa \"Sala de Embarque\" tenha acesso a diversos grupos para interagir com a comunidade					</p>\n		<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\"}}},\"backgroundColor\":\"ast-global-color-5\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}}} -->\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":134,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<h2>NÃO FIQUE DE FORA</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaPosition\":\"right\",\"mediaId\":43,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=43\",\"linkDestination\":\"custom\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"imageFill\":false,\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"}},\"textColor\":\"ast-global-color-4\"} -->\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}},\"textColor\":\"ast-global-color-5\"} -->\n<h2 style=\"padding-right: 40px;\">NERD EXPERIENCE 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<figure><a href=\"https://nerdexperience.com.br/\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/326133700_189372070344481_5452170378878663579_n-1024x1024.jpeg\" alt=\"\" /></a></figure>\n<!-- /wp:media-text --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textColor\":\"ast-global-color-5\"} -->\n<h2>FIQUE LIGADO!</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaId\":59,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=59\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"}}} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/322515922_5441748755952564_4142625563983561065_n-1024x1024.jpeg\" alt=\"\" /></figure>\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}}} -->\n<h2 style=\"padding-right: 40px;\">COVIL CON 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<!-- /wp:media-text -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"wide\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>O QUE JÁ ACONTECEU</h2>\n<!-- /wp:heading --><!-- wp:heading {\"level\":3} -->\n<h3>Math Trade Belo Horizonte - Fevereiro 2023</h3>\n<!-- /wp:heading --><!-- wp:columns -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/o-que-e-uma-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Explicamos o que é <br />uma Math Trade</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Se não sabe o que é uma Math Trade, nós ajudamos. Temos uma página com explicações básicas do que é e como funciona uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":41,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/regras-gerais-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Conheça um pouco <br />mais das regras</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Agora que já sabe o que é, pode dar uma olhada na nossa página de regras gerais para se ambientar e estar pronto a participar de uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/615x330-MT-Fev23.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Math Trade BH <br />5a edição</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>No começo de Fevereiro de 2023 realizamos a 5a edição da Math Trade BH. Como sempre, um sucesso de cadastros e trocas.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns --><!-- wp:spacer {\"height\":\"40px\"} -->\n \n<!-- /wp:spacer --><!-- wp:heading {\"level\":3} -->\n<h3>NOSSOS TORNEIOS</h3>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"wide\",\"mediaId\":55,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=55\",\"mediaType\":\"image\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/Carcassonne-Banner-Web-1024x347.png\" alt=\"\" /></figure>\n<!-- wp:paragraph {\"placeholder\":\"Conteúdo...\"} -->\n<p><strong>ENCERRADO</strong></p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Em 2022 realizamos etapas regionais de Carcassonne, classificatórias para o nacional. Em 2023 teremos mais novidades</p>\n<!-- /wp:paragraph -->\n<!-- /wp:media-text --><!-- wp:paragraph -->\n<p>TORNEIOS REALIZADOS</p>\n<!-- /wp:paragraph --><!-- wp:gallery {\"columns\":6,\"linkTo\":\"none\",\"sizeSlug\":\"full\"} -->\n<figure><!-- wp:image {\"id\":56,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-1.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":52,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":47,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":48,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":49,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale.png\" alt=\"\" /></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery --><!-- wp:spacer {\"height\":\"0px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\"},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":false,\"contentSize\":\"800px\",\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":235,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/avatar.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"22px\",\"lineHeight\":1.6}},\"textColor\":\"ast-global-color-5\"} -->\n<p style=\"font-size: 22px; line-height: 1.6;\">“The best part is that Astra comes with hundreds of professionally designed templates for just about every industry, makes it super easy for non-techy users to build a website.”</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"ast-global-color-8\"} -->\n<p><strong>Wade Warren</strong></p>\n<!-- /wp:paragraph -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}}},\"textColor\":\"ast-global-color-4\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>NOSSOS GRUPOS</h2>\n<!-- /wp:heading --><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"80px\",\"margin\":{\"top\":\"60px\"}}}} -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":44,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-trocas-vendas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - TROCAS &amp; VENDAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">O grupo é <strong>EXCLUSIVO</strong> para Belo Horizonte e Região* e tem como foco os anúncios de trocas e vendas diretamente entre seus usuários. O grupo possui regras bem definidas para otimizar sua funcionalidade.<br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Chat moderado.</strong> </mark><mark style=\"background-color: rgba(0, 0, 0, 0);\"> </mark></p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p><mark style=\"background-color: rgba(0, 0, 0, 0);\">* Participação limitada a usuários que consigam entregar os jogos em Belo Horizonte</mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":45,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-resenha.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - RESENHA</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para a interação entre amantes de Boardgame. BG é o que nos une mas um bom papo fora do tema não é proibido. Novidades, jogatinas online, presenciais, dúvidas sobre regras, indicações. Aqui é o lugar. A única exigência é o bom senso.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem restrições</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":46,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-ofertas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - OFERTAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para divulgação de oportunidades e ofertas de Boardgames. Aqui é permitido a divulgação de anúncios em plataformas oficiais além de promoções em luderias e sites. Suas regras e funcionalidade ainda estão sendo definidas.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem chat</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%)\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"medium\"} -->\n<h2 style=\"color: #ffffff; font-style: normal; font-weight: 400;\">ENTRE EM CONTATO CONOSCO E SEJA UM APOIADOR OU PARCEIRO DO NOSSO PROJETO</h2>\n<!-- /wp:heading -->\n<!-- /wp:group -->		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>TORNEIOS REALIZADOS</h2>		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-widget-image-carousel .swiper,.elementor-widget-image-carousel .swiper-container{position:static}.elementor-widget-image-carousel .swiper-container .swiper-slide figure,.elementor-widget-image-carousel .swiper .swiper-slide figure{line-height:inherit}.elementor-widget-image-carousel .swiper-slide{text-align:center}.elementor-image-carousel-wrapper:not(.swiper-container-initialized):not(.swiper-initialized) .swiper-slide{max-width:calc(100% / var(--e-image-carousel-slides-to-show, 3))}</style>		\n								<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne-300x161.png\" alt=\"torneio-carcassonne\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-300x161.png\" alt=\"torneio-draftosaurus\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel-300x161.png\" alt=\"torneio-7wduel\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express-300x161.png\" alt=\"torneio-colt-express\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur-300x161.png\" alt=\"torneio-jaipur\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale-300x161.png\" alt=\"torneio-forsale\" /></figure><figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/desafio-sushigo-300x161.png\" alt=\"desafio-sushigo\" /></figure>', 'Home', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2023-12-23 08:04:38', '2023-12-23 11:04:38', '', 16, 'https://bgbh.com.br/blog/?p=521', 0, 'revision', '', 0);
INSERT INTO `wptask_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(522, 1, '2023-12-23 08:04:39', '2023-12-23 11:04:39', '<link rel=\"stylesheet\" href=\"https://bgbh.com.br/blog/wp-content/plugins/elementor/assets/css/widget-icon-box.min.css\">		\n				<h3>\n						MATH TRADE BH					\n				</h3>\n									<p>\n						Organizamos a maior Math Trade regional do Brasil, a Math Trade BH					</p>\n				<h3>\n						Arena de Jogos					\n				</h3>\n									<p>\n						Estamos presente no maior evento geek de MG, o Nerd Experience, além de outros eventos Geek					</p>\n				<h3>\n						Grupos de discussão					\n				</h3>\n									<p>\n						Através da nossa \"Sala de Embarque\" tenha acesso a diversos grupos para interagir com a comunidade					</p>\n		<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\"}}},\"backgroundColor\":\"ast-global-color-5\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}}} -->\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":134,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<h2>NÃO FIQUE DE FORA</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaPosition\":\"right\",\"mediaId\":43,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=43\",\"linkDestination\":\"custom\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"imageFill\":false,\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"}},\"textColor\":\"ast-global-color-4\"} -->\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}},\"textColor\":\"ast-global-color-5\"} -->\n<h2 style=\"padding-right: 40px;\">NERD EXPERIENCE 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<figure><a href=\"https://nerdexperience.com.br/\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/326133700_189372070344481_5452170378878663579_n-1024x1024.jpeg\" alt=\"\" /></a></figure>\n<!-- /wp:media-text --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textColor\":\"ast-global-color-5\"} -->\n<h2>FIQUE LIGADO!</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaId\":59,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=59\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"}}} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/322515922_5441748755952564_4142625563983561065_n-1024x1024.jpeg\" alt=\"\" /></figure>\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}}} -->\n<h2 style=\"padding-right: 40px;\">COVIL CON 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<!-- /wp:media-text -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"wide\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>O QUE JÁ ACONTECEU</h2>\n<!-- /wp:heading --><!-- wp:heading {\"level\":3} -->\n<h3>Math Trade Belo Horizonte - Fevereiro 2023</h3>\n<!-- /wp:heading --><!-- wp:columns -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/o-que-e-uma-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Explicamos o que é <br />uma Math Trade</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Se não sabe o que é uma Math Trade, nós ajudamos. Temos uma página com explicações básicas do que é e como funciona uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":41,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/regras-gerais-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Conheça um pouco <br />mais das regras</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Agora que já sabe o que é, pode dar uma olhada na nossa página de regras gerais para se ambientar e estar pronto a participar de uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/615x330-MT-Fev23.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Math Trade BH <br />5a edição</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>No começo de Fevereiro de 2023 realizamos a 5a edição da Math Trade BH. Como sempre, um sucesso de cadastros e trocas.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns --><!-- wp:spacer {\"height\":\"40px\"} -->\n \n<!-- /wp:spacer --><!-- wp:heading {\"level\":3} -->\n<h3>NOSSOS TORNEIOS</h3>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"wide\",\"mediaId\":55,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=55\",\"mediaType\":\"image\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/Carcassonne-Banner-Web-1024x347.png\" alt=\"\" /></figure>\n<!-- wp:paragraph {\"placeholder\":\"Conteúdo...\"} -->\n<p><strong>ENCERRADO</strong></p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Em 2022 realizamos etapas regionais de Carcassonne, classificatórias para o nacional. Em 2023 teremos mais novidades</p>\n<!-- /wp:paragraph -->\n<!-- /wp:media-text --><!-- wp:paragraph -->\n<p>TORNEIOS REALIZADOS</p>\n<!-- /wp:paragraph --><!-- wp:gallery {\"columns\":6,\"linkTo\":\"none\",\"sizeSlug\":\"full\"} -->\n<figure><!-- wp:image {\"id\":56,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-1.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":52,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":47,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":48,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":49,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale.png\" alt=\"\" /></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery --><!-- wp:spacer {\"height\":\"0px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\"},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":false,\"contentSize\":\"800px\",\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":235,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/avatar.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"22px\",\"lineHeight\":1.6}},\"textColor\":\"ast-global-color-5\"} -->\n<p style=\"font-size: 22px; line-height: 1.6;\">“The best part is that Astra comes with hundreds of professionally designed templates for just about every industry, makes it super easy for non-techy users to build a website.”</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"ast-global-color-8\"} -->\n<p><strong>Wade Warren</strong></p>\n<!-- /wp:paragraph -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}}},\"textColor\":\"ast-global-color-4\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>NOSSOS GRUPOS</h2>\n<!-- /wp:heading --><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"80px\",\"margin\":{\"top\":\"60px\"}}}} -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":44,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-trocas-vendas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - TROCAS &amp; VENDAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">O grupo é <strong>EXCLUSIVO</strong> para Belo Horizonte e Região* e tem como foco os anúncios de trocas e vendas diretamente entre seus usuários. O grupo possui regras bem definidas para otimizar sua funcionalidade.<br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Chat moderado.</strong> </mark><mark style=\"background-color: rgba(0, 0, 0, 0);\"> </mark></p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p><mark style=\"background-color: rgba(0, 0, 0, 0);\">* Participação limitada a usuários que consigam entregar os jogos em Belo Horizonte</mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":45,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-resenha.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - RESENHA</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para a interação entre amantes de Boardgame. BG é o que nos une mas um bom papo fora do tema não é proibido. Novidades, jogatinas online, presenciais, dúvidas sobre regras, indicações. Aqui é o lugar. A única exigência é o bom senso.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem restrições</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":46,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-ofertas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - OFERTAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para divulgação de oportunidades e ofertas de Boardgames. Aqui é permitido a divulgação de anúncios em plataformas oficiais além de promoções em luderias e sites. Suas regras e funcionalidade ainda estão sendo definidas.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem chat</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%)\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"medium\"} -->\n<h2 style=\"color: #ffffff; font-style: normal; font-weight: 400;\">ENTRE EM CONTATO CONOSCO E SEJA UM APOIADOR OU PARCEIRO DO NOSSO PROJETO</h2>\n<!-- /wp:heading -->\n<!-- /wp:group -->		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>TORNEIOS REALIZADOS</h2>		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-widget-image-carousel .swiper,.elementor-widget-image-carousel .swiper-container{position:static}.elementor-widget-image-carousel .swiper-container .swiper-slide figure,.elementor-widget-image-carousel .swiper .swiper-slide figure{line-height:inherit}.elementor-widget-image-carousel .swiper-slide{text-align:center}.elementor-image-carousel-wrapper:not(.swiper-container-initialized):not(.swiper-initialized) .swiper-slide{max-width:calc(100% / var(--e-image-carousel-slides-to-show, 3))}</style>		\n								<figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne-300x161.png\" alt=\"torneio-carcassonne\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-300x161.png\" alt=\"torneio-draftosaurus\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel-300x161.png\" alt=\"torneio-7wduel\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express-300x161.png\" alt=\"torneio-colt-express\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur-300x161.png\" alt=\"torneio-jaipur\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale-300x161.png\" alt=\"torneio-forsale\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/desafio-sushigo-300x161.png\" alt=\"desafio-sushigo\" /></figure>', 'Home', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2023-12-23 08:04:39', '2023-12-23 11:04:39', '', 16, 'https://bgbh.com.br/blog/?p=522', 0, 'revision', '', 0),
(523, 1, '2023-12-23 08:05:30', '2023-12-23 11:05:30', '<link rel=\"stylesheet\" href=\"https://bgbh.com.br/blog/wp-content/plugins/elementor/assets/css/widget-icon-box.min.css\">		\n				<h3>\n						MATH TRADE BH					\n				</h3>\n									<p>\n						Organizamos a maior Math Trade regional do Brasil, a Math Trade BH					</p>\n				<h3>\n						Arena de Jogos					\n				</h3>\n									<p>\n						Estamos presente no maior evento geek de MG, o Nerd Experience, além de outros eventos Geek					</p>\n				<h3>\n						Grupos de discussão					\n				</h3>\n									<p>\n						Através da nossa \"Sala de Embarque\" tenha acesso a diversos grupos para interagir com a comunidade					</p>\n		<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\"}}},\"backgroundColor\":\"ast-global-color-5\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}}} -->\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":134,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<h2>NÃO FIQUE DE FORA</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaPosition\":\"right\",\"mediaId\":43,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=43\",\"linkDestination\":\"custom\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"imageFill\":false,\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"}},\"textColor\":\"ast-global-color-4\"} -->\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}},\"textColor\":\"ast-global-color-5\"} -->\n<h2 style=\"padding-right: 40px;\">NERD EXPERIENCE 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<figure><a href=\"https://nerdexperience.com.br/\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/326133700_189372070344481_5452170378878663579_n-1024x1024.jpeg\" alt=\"\" /></a></figure>\n<!-- /wp:media-text --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textColor\":\"ast-global-color-5\"} -->\n<h2>FIQUE LIGADO!</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaId\":59,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=59\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"}}} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/322515922_5441748755952564_4142625563983561065_n-1024x1024.jpeg\" alt=\"\" /></figure>\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}}} -->\n<h2 style=\"padding-right: 40px;\">COVIL CON 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<!-- /wp:media-text -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"wide\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>O QUE JÁ ACONTECEU</h2>\n<!-- /wp:heading --><!-- wp:heading {\"level\":3} -->\n<h3>Math Trade Belo Horizonte - Fevereiro 2023</h3>\n<!-- /wp:heading --><!-- wp:columns -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/o-que-e-uma-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Explicamos o que é <br />uma Math Trade</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Se não sabe o que é uma Math Trade, nós ajudamos. Temos uma página com explicações básicas do que é e como funciona uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":41,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/regras-gerais-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Conheça um pouco <br />mais das regras</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Agora que já sabe o que é, pode dar uma olhada na nossa página de regras gerais para se ambientar e estar pronto a participar de uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/615x330-MT-Fev23.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Math Trade BH <br />5a edição</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>No começo de Fevereiro de 2023 realizamos a 5a edição da Math Trade BH. Como sempre, um sucesso de cadastros e trocas.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns --><!-- wp:spacer {\"height\":\"40px\"} -->\n \n<!-- /wp:spacer --><!-- wp:heading {\"level\":3} -->\n<h3>NOSSOS TORNEIOS</h3>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"wide\",\"mediaId\":55,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=55\",\"mediaType\":\"image\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/Carcassonne-Banner-Web-1024x347.png\" alt=\"\" /></figure>\n<!-- wp:paragraph {\"placeholder\":\"Conteúdo...\"} -->\n<p><strong>ENCERRADO</strong></p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Em 2022 realizamos etapas regionais de Carcassonne, classificatórias para o nacional. Em 2023 teremos mais novidades</p>\n<!-- /wp:paragraph -->\n<!-- /wp:media-text --><!-- wp:paragraph -->\n<p>TORNEIOS REALIZADOS</p>\n<!-- /wp:paragraph --><!-- wp:gallery {\"columns\":6,\"linkTo\":\"none\",\"sizeSlug\":\"full\"} -->\n<figure><!-- wp:image {\"id\":56,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-1.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":52,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":47,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":48,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":49,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale.png\" alt=\"\" /></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery --><!-- wp:spacer {\"height\":\"0px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\"},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":false,\"contentSize\":\"800px\",\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":235,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/avatar.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"22px\",\"lineHeight\":1.6}},\"textColor\":\"ast-global-color-5\"} -->\n<p style=\"font-size: 22px; line-height: 1.6;\">“The best part is that Astra comes with hundreds of professionally designed templates for just about every industry, makes it super easy for non-techy users to build a website.”</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"ast-global-color-8\"} -->\n<p><strong>Wade Warren</strong></p>\n<!-- /wp:paragraph -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}}},\"textColor\":\"ast-global-color-4\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>NOSSOS GRUPOS</h2>\n<!-- /wp:heading --><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"80px\",\"margin\":{\"top\":\"60px\"}}}} -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":44,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-trocas-vendas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - TROCAS &amp; VENDAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">O grupo é <strong>EXCLUSIVO</strong> para Belo Horizonte e Região* e tem como foco os anúncios de trocas e vendas diretamente entre seus usuários. O grupo possui regras bem definidas para otimizar sua funcionalidade.<br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Chat moderado.</strong> </mark><mark style=\"background-color: rgba(0, 0, 0, 0);\"> </mark></p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p><mark style=\"background-color: rgba(0, 0, 0, 0);\">* Participação limitada a usuários que consigam entregar os jogos em Belo Horizonte</mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":45,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-resenha.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - RESENHA</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para a interação entre amantes de Boardgame. BG é o que nos une mas um bom papo fora do tema não é proibido. Novidades, jogatinas online, presenciais, dúvidas sobre regras, indicações. Aqui é o lugar. A única exigência é o bom senso.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem restrições</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":46,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-ofertas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - OFERTAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para divulgação de oportunidades e ofertas de Boardgames. Aqui é permitido a divulgação de anúncios em plataformas oficiais além de promoções em luderias e sites. Suas regras e funcionalidade ainda estão sendo definidas.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem chat</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%)\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"medium\"} -->\n<h2 style=\"color: #ffffff; font-style: normal; font-weight: 400;\">ENTRE EM CONTATO CONOSCO E SEJA UM APOIADOR OU PARCEIRO DO NOSSO PROJETO</h2>\n<!-- /wp:heading -->\n<!-- /wp:group -->		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>TORNEIOS REALIZADOS</h2>		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-widget-image-carousel .swiper,.elementor-widget-image-carousel .swiper-container{position:static}.elementor-widget-image-carousel .swiper-container .swiper-slide figure,.elementor-widget-image-carousel .swiper .swiper-slide figure{line-height:inherit}.elementor-widget-image-carousel .swiper-slide{text-align:center}.elementor-image-carousel-wrapper:not(.swiper-container-initialized):not(.swiper-initialized) .swiper-slide{max-width:calc(100% / var(--e-image-carousel-slides-to-show, 3))}</style>		\n								<figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne-300x161.png\" alt=\"torneio-carcassonne\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-300x161.png\" alt=\"torneio-draftosaurus\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel-300x161.png\" alt=\"torneio-7wduel\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express-300x161.png\" alt=\"torneio-colt-express\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur-300x161.png\" alt=\"torneio-jaipur\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale-300x161.png\" alt=\"torneio-forsale\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/desafio-sushigo-300x161.png\" alt=\"desafio-sushigo\" /></figure>', 'Home', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2023-12-23 08:05:30', '2023-12-23 11:05:30', '', 16, 'https://bgbh.com.br/blog/?p=523', 0, 'revision', '', 0);
INSERT INTO `wptask_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(524, 1, '2023-12-23 08:05:30', '2023-12-23 11:05:30', '<link rel=\"stylesheet\" href=\"https://bgbh.com.br/blog/wp-content/plugins/elementor/assets/css/widget-icon-box.min.css\">		\n				<h3>\n						MATH TRADE BH					\n				</h3>\n									<p>\n						Organizamos a maior Math Trade regional do Brasil, a Math Trade BH					</p>\n				<h3>\n						Arena de Jogos					\n				</h3>\n									<p>\n						Estamos presente no maior evento geek de MG, o Nerd Experience, além de outros eventos Geek					</p>\n				<h3>\n						Grupos de discussão					\n				</h3>\n									<p>\n						Através da nossa \"Sala de Embarque\" tenha acesso a diversos grupos para interagir com a comunidade					</p>\n		<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\"}}},\"backgroundColor\":\"ast-global-color-5\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}}} -->\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":134,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<h2>NÃO FIQUE DE FORA</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaPosition\":\"right\",\"mediaId\":43,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=43\",\"linkDestination\":\"custom\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"imageFill\":false,\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"}},\"textColor\":\"ast-global-color-4\"} -->\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}},\"textColor\":\"ast-global-color-5\"} -->\n<h2 style=\"padding-right: 40px;\">NERD EXPERIENCE 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<figure><a href=\"https://nerdexperience.com.br/\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/326133700_189372070344481_5452170378878663579_n-1024x1024.jpeg\" alt=\"\" /></a></figure>\n<!-- /wp:media-text --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textColor\":\"ast-global-color-5\"} -->\n<h2>FIQUE LIGADO!</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaId\":59,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=59\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"}}} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/322515922_5441748755952564_4142625563983561065_n-1024x1024.jpeg\" alt=\"\" /></figure>\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}}} -->\n<h2 style=\"padding-right: 40px;\">COVIL CON 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<!-- /wp:media-text -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"wide\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>O QUE JÁ ACONTECEU</h2>\n<!-- /wp:heading --><!-- wp:heading {\"level\":3} -->\n<h3>Math Trade Belo Horizonte - Fevereiro 2023</h3>\n<!-- /wp:heading --><!-- wp:columns -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/o-que-e-uma-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Explicamos o que é <br />uma Math Trade</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Se não sabe o que é uma Math Trade, nós ajudamos. Temos uma página com explicações básicas do que é e como funciona uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":41,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/regras-gerais-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Conheça um pouco <br />mais das regras</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Agora que já sabe o que é, pode dar uma olhada na nossa página de regras gerais para se ambientar e estar pronto a participar de uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/615x330-MT-Fev23.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Math Trade BH <br />5a edição</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>No começo de Fevereiro de 2023 realizamos a 5a edição da Math Trade BH. Como sempre, um sucesso de cadastros e trocas.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns --><!-- wp:spacer {\"height\":\"40px\"} -->\n \n<!-- /wp:spacer --><!-- wp:heading {\"level\":3} -->\n<h3>NOSSOS TORNEIOS</h3>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"wide\",\"mediaId\":55,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=55\",\"mediaType\":\"image\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/Carcassonne-Banner-Web-1024x347.png\" alt=\"\" /></figure>\n<!-- wp:paragraph {\"placeholder\":\"Conteúdo...\"} -->\n<p><strong>ENCERRADO</strong></p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Em 2022 realizamos etapas regionais de Carcassonne, classificatórias para o nacional. Em 2023 teremos mais novidades</p>\n<!-- /wp:paragraph -->\n<!-- /wp:media-text --><!-- wp:paragraph -->\n<p>TORNEIOS REALIZADOS</p>\n<!-- /wp:paragraph --><!-- wp:gallery {\"columns\":6,\"linkTo\":\"none\",\"sizeSlug\":\"full\"} -->\n<figure><!-- wp:image {\"id\":56,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-1.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":52,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":47,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":48,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":49,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale.png\" alt=\"\" /></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery --><!-- wp:spacer {\"height\":\"0px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\"},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":false,\"contentSize\":\"800px\",\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":235,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/avatar.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"22px\",\"lineHeight\":1.6}},\"textColor\":\"ast-global-color-5\"} -->\n<p style=\"font-size: 22px; line-height: 1.6;\">“The best part is that Astra comes with hundreds of professionally designed templates for just about every industry, makes it super easy for non-techy users to build a website.”</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"ast-global-color-8\"} -->\n<p><strong>Wade Warren</strong></p>\n<!-- /wp:paragraph -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}}},\"textColor\":\"ast-global-color-4\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>NOSSOS GRUPOS</h2>\n<!-- /wp:heading --><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"80px\",\"margin\":{\"top\":\"60px\"}}}} -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":44,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-trocas-vendas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - TROCAS &amp; VENDAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">O grupo é <strong>EXCLUSIVO</strong> para Belo Horizonte e Região* e tem como foco os anúncios de trocas e vendas diretamente entre seus usuários. O grupo possui regras bem definidas para otimizar sua funcionalidade.<br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Chat moderado.</strong> </mark><mark style=\"background-color: rgba(0, 0, 0, 0);\"> </mark></p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p><mark style=\"background-color: rgba(0, 0, 0, 0);\">* Participação limitada a usuários que consigam entregar os jogos em Belo Horizonte</mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":45,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-resenha.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - RESENHA</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para a interação entre amantes de Boardgame. BG é o que nos une mas um bom papo fora do tema não é proibido. Novidades, jogatinas online, presenciais, dúvidas sobre regras, indicações. Aqui é o lugar. A única exigência é o bom senso.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem restrições</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":46,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-ofertas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - OFERTAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para divulgação de oportunidades e ofertas de Boardgames. Aqui é permitido a divulgação de anúncios em plataformas oficiais além de promoções em luderias e sites. Suas regras e funcionalidade ainda estão sendo definidas.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem chat</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%)\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"medium\"} -->\n<h2 style=\"color: #ffffff; font-style: normal; font-weight: 400;\">ENTRE EM CONTATO CONOSCO E SEJA UM APOIADOR OU PARCEIRO DO NOSSO PROJETO</h2>\n<!-- /wp:heading -->\n<!-- /wp:group -->		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>TORNEIOS REALIZADOS</h2>		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-widget-image-carousel .swiper,.elementor-widget-image-carousel .swiper-container{position:static}.elementor-widget-image-carousel .swiper-container .swiper-slide figure,.elementor-widget-image-carousel .swiper .swiper-slide figure{line-height:inherit}.elementor-widget-image-carousel .swiper-slide{text-align:center}.elementor-image-carousel-wrapper:not(.swiper-container-initialized):not(.swiper-initialized) .swiper-slide{max-width:calc(100% / var(--e-image-carousel-slides-to-show, 3))}</style>		\n								<figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne-300x161.png\" alt=\"torneio-carcassonne\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-300x161.png\" alt=\"torneio-draftosaurus\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel-300x161.png\" alt=\"torneio-7wduel\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express-300x161.png\" alt=\"torneio-colt-express\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur-300x161.png\" alt=\"torneio-jaipur\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale-300x161.png\" alt=\"torneio-forsale\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/desafio-sushigo-300x161.png\" alt=\"desafio-sushigo\" /></figure>', 'Home', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2023-12-23 08:05:30', '2023-12-23 11:05:30', '', 16, 'https://bgbh.com.br/blog/?p=524', 0, 'revision', '', 0),
(525, 1, '2023-12-23 08:05:30', '2023-12-23 11:05:30', '<link rel=\"stylesheet\" href=\"https://bgbh.com.br/blog/wp-content/plugins/elementor/assets/css/widget-icon-box.min.css\">		\n				<h3>\n						MATH TRADE BH					\n				</h3>\n									<p>\n						Organizamos a maior Math Trade regional do Brasil, a Math Trade BH					</p>\n				<h3>\n						Arena de Jogos					\n				</h3>\n									<p>\n						Estamos presente no maior evento geek de MG, o Nerd Experience, além de outros eventos Geek					</p>\n				<h3>\n						Grupos de discussão					\n				</h3>\n									<p>\n						Através da nossa \"Sala de Embarque\" tenha acesso a diversos grupos para interagir com a comunidade					</p>\n		<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\"}}},\"backgroundColor\":\"ast-global-color-5\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}}} -->\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":134,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<h2>NÃO FIQUE DE FORA</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaPosition\":\"right\",\"mediaId\":43,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=43\",\"linkDestination\":\"custom\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"imageFill\":false,\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"}},\"textColor\":\"ast-global-color-4\"} -->\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}},\"textColor\":\"ast-global-color-5\"} -->\n<h2 style=\"padding-right: 40px;\">NERD EXPERIENCE 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<figure><a href=\"https://nerdexperience.com.br/\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/326133700_189372070344481_5452170378878663579_n-1024x1024.jpeg\" alt=\"\" /></a></figure>\n<!-- /wp:media-text --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textColor\":\"ast-global-color-5\"} -->\n<h2>FIQUE LIGADO!</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaId\":59,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=59\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"}}} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/322515922_5441748755952564_4142625563983561065_n-1024x1024.jpeg\" alt=\"\" /></figure>\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}}} -->\n<h2 style=\"padding-right: 40px;\">COVIL CON 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<!-- /wp:media-text -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"wide\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>O QUE JÁ ACONTECEU</h2>\n<!-- /wp:heading --><!-- wp:heading {\"level\":3} -->\n<h3>Math Trade Belo Horizonte - Fevereiro 2023</h3>\n<!-- /wp:heading --><!-- wp:columns -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/o-que-e-uma-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Explicamos o que é <br />uma Math Trade</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Se não sabe o que é uma Math Trade, nós ajudamos. Temos uma página com explicações básicas do que é e como funciona uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":41,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/regras-gerais-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Conheça um pouco <br />mais das regras</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Agora que já sabe o que é, pode dar uma olhada na nossa página de regras gerais para se ambientar e estar pronto a participar de uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/615x330-MT-Fev23.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Math Trade BH <br />5a edição</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>No começo de Fevereiro de 2023 realizamos a 5a edição da Math Trade BH. Como sempre, um sucesso de cadastros e trocas.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns --><!-- wp:spacer {\"height\":\"40px\"} -->\n \n<!-- /wp:spacer --><!-- wp:heading {\"level\":3} -->\n<h3>NOSSOS TORNEIOS</h3>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"wide\",\"mediaId\":55,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=55\",\"mediaType\":\"image\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/Carcassonne-Banner-Web-1024x347.png\" alt=\"\" /></figure>\n<!-- wp:paragraph {\"placeholder\":\"Conteúdo...\"} -->\n<p><strong>ENCERRADO</strong></p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Em 2022 realizamos etapas regionais de Carcassonne, classificatórias para o nacional. Em 2023 teremos mais novidades</p>\n<!-- /wp:paragraph -->\n<!-- /wp:media-text --><!-- wp:paragraph -->\n<p>TORNEIOS REALIZADOS</p>\n<!-- /wp:paragraph --><!-- wp:gallery {\"columns\":6,\"linkTo\":\"none\",\"sizeSlug\":\"full\"} -->\n<figure><!-- wp:image {\"id\":56,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-1.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":52,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":47,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":48,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":49,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale.png\" alt=\"\" /></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery --><!-- wp:spacer {\"height\":\"0px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\"},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":false,\"contentSize\":\"800px\",\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":235,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/avatar.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"22px\",\"lineHeight\":1.6}},\"textColor\":\"ast-global-color-5\"} -->\n<p style=\"font-size: 22px; line-height: 1.6;\">“The best part is that Astra comes with hundreds of professionally designed templates for just about every industry, makes it super easy for non-techy users to build a website.”</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"ast-global-color-8\"} -->\n<p><strong>Wade Warren</strong></p>\n<!-- /wp:paragraph -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}}},\"textColor\":\"ast-global-color-4\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>NOSSOS GRUPOS</h2>\n<!-- /wp:heading --><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"80px\",\"margin\":{\"top\":\"60px\"}}}} -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":44,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-trocas-vendas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - TROCAS &amp; VENDAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">O grupo é <strong>EXCLUSIVO</strong> para Belo Horizonte e Região* e tem como foco os anúncios de trocas e vendas diretamente entre seus usuários. O grupo possui regras bem definidas para otimizar sua funcionalidade.<br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Chat moderado.</strong> </mark><mark style=\"background-color: rgba(0, 0, 0, 0);\"> </mark></p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p><mark style=\"background-color: rgba(0, 0, 0, 0);\">* Participação limitada a usuários que consigam entregar os jogos em Belo Horizonte</mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":45,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-resenha.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - RESENHA</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para a interação entre amantes de Boardgame. BG é o que nos une mas um bom papo fora do tema não é proibido. Novidades, jogatinas online, presenciais, dúvidas sobre regras, indicações. Aqui é o lugar. A única exigência é o bom senso.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem restrições</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":46,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-ofertas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - OFERTAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para divulgação de oportunidades e ofertas de Boardgames. Aqui é permitido a divulgação de anúncios em plataformas oficiais além de promoções em luderias e sites. Suas regras e funcionalidade ainda estão sendo definidas.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem chat</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%)\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"medium\"} -->\n<h2 style=\"color: #ffffff; font-style: normal; font-weight: 400;\">ENTRE EM CONTATO CONOSCO E SEJA UM APOIADOR OU PARCEIRO DO NOSSO PROJETO</h2>\n<!-- /wp:heading -->\n<!-- /wp:group -->		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>TORNEIOS REALIZADOS</h2>		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-widget-image-carousel .swiper,.elementor-widget-image-carousel .swiper-container{position:static}.elementor-widget-image-carousel .swiper-container .swiper-slide figure,.elementor-widget-image-carousel .swiper .swiper-slide figure{line-height:inherit}.elementor-widget-image-carousel .swiper-slide{text-align:center}.elementor-image-carousel-wrapper:not(.swiper-container-initialized):not(.swiper-initialized) .swiper-slide{max-width:calc(100% / var(--e-image-carousel-slides-to-show, 3))}</style>		\n								<figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne-300x161.png\" alt=\"torneio-carcassonne\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-300x161.png\" alt=\"torneio-draftosaurus\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel-300x161.png\" alt=\"torneio-7wduel\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express-300x161.png\" alt=\"torneio-colt-express\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur-300x161.png\" alt=\"torneio-jaipur\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale-300x161.png\" alt=\"torneio-forsale\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/desafio-sushigo-300x161.png\" alt=\"desafio-sushigo\" /></figure>', 'Home', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2023-12-23 08:05:30', '2023-12-23 11:05:30', '', 16, 'https://bgbh.com.br/blog/?p=525', 0, 'revision', '', 0);
INSERT INTO `wptask_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(526, 1, '2023-12-23 08:17:54', '2023-12-23 11:17:54', '<link rel=\"stylesheet\" href=\"https://bgbh.com.br/blog/wp-content/plugins/elementor/assets/css/widget-icon-box.min.css\">		\n				<h3>\n						MATH TRADE BH					\n				</h3>\n									<p>\n						Organizamos a maior Math Trade regional do Brasil, a Math Trade BH					</p>\n				<h3>\n						Arena de Jogos					\n				</h3>\n									<p>\n						Estamos presente no maior evento geek de MG, o Nerd Experience, além de outros eventos Geek					</p>\n				<h3>\n						Grupos de discussão					\n				</h3>\n									<p>\n						Através da nossa \"Sala de Embarque\" tenha acesso a diversos grupos para interagir com a comunidade					</p>\n		<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\"}}},\"backgroundColor\":\"ast-global-color-5\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}}} -->\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":134,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<h2>NÃO FIQUE DE FORA</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaPosition\":\"right\",\"mediaId\":43,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=43\",\"linkDestination\":\"custom\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"imageFill\":false,\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"}},\"textColor\":\"ast-global-color-4\"} -->\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}},\"textColor\":\"ast-global-color-5\"} -->\n<h2 style=\"padding-right: 40px;\">NERD EXPERIENCE 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<figure><a href=\"https://nerdexperience.com.br/\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/326133700_189372070344481_5452170378878663579_n-1024x1024.jpeg\" alt=\"\" /></a></figure>\n<!-- /wp:media-text --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textColor\":\"ast-global-color-5\"} -->\n<h2>FIQUE LIGADO!</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaId\":59,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=59\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"}}} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/322515922_5441748755952564_4142625563983561065_n-1024x1024.jpeg\" alt=\"\" /></figure>\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}}} -->\n<h2 style=\"padding-right: 40px;\">COVIL CON 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<!-- /wp:media-text -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"wide\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>O QUE JÁ ACONTECEU</h2>\n<!-- /wp:heading --><!-- wp:heading {\"level\":3} -->\n<h3>Math Trade Belo Horizonte - Fevereiro 2023</h3>\n<!-- /wp:heading --><!-- wp:columns -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/o-que-e-uma-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Explicamos o que é <br />uma Math Trade</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Se não sabe o que é uma Math Trade, nós ajudamos. Temos uma página com explicações básicas do que é e como funciona uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":41,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/regras-gerais-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Conheça um pouco <br />mais das regras</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Agora que já sabe o que é, pode dar uma olhada na nossa página de regras gerais para se ambientar e estar pronto a participar de uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/615x330-MT-Fev23.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Math Trade BH <br />5a edição</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>No começo de Fevereiro de 2023 realizamos a 5a edição da Math Trade BH. Como sempre, um sucesso de cadastros e trocas.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns --><!-- wp:spacer {\"height\":\"40px\"} -->\n \n<!-- /wp:spacer --><!-- wp:heading {\"level\":3} -->\n<h3>NOSSOS TORNEIOS</h3>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"wide\",\"mediaId\":55,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=55\",\"mediaType\":\"image\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/Carcassonne-Banner-Web-1024x347.png\" alt=\"\" /></figure>\n<!-- wp:paragraph {\"placeholder\":\"Conteúdo...\"} -->\n<p><strong>ENCERRADO</strong></p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Em 2022 realizamos etapas regionais de Carcassonne, classificatórias para o nacional. Em 2023 teremos mais novidades</p>\n<!-- /wp:paragraph -->\n<!-- /wp:media-text --><!-- wp:paragraph -->\n<p>TORNEIOS REALIZADOS</p>\n<!-- /wp:paragraph --><!-- wp:gallery {\"columns\":6,\"linkTo\":\"none\",\"sizeSlug\":\"full\"} -->\n<figure><!-- wp:image {\"id\":56,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-1.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":52,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":47,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":48,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":49,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale.png\" alt=\"\" /></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery --><!-- wp:spacer {\"height\":\"0px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\"},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":false,\"contentSize\":\"800px\",\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":235,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/avatar.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"22px\",\"lineHeight\":1.6}},\"textColor\":\"ast-global-color-5\"} -->\n<p style=\"font-size: 22px; line-height: 1.6;\">“The best part is that Astra comes with hundreds of professionally designed templates for just about every industry, makes it super easy for non-techy users to build a website.”</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"ast-global-color-8\"} -->\n<p><strong>Wade Warren</strong></p>\n<!-- /wp:paragraph -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}}},\"textColor\":\"ast-global-color-4\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>NOSSOS GRUPOS</h2>\n<!-- /wp:heading --><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"80px\",\"margin\":{\"top\":\"60px\"}}}} -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":44,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-trocas-vendas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - TROCAS &amp; VENDAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">O grupo é <strong>EXCLUSIVO</strong> para Belo Horizonte e Região* e tem como foco os anúncios de trocas e vendas diretamente entre seus usuários. O grupo possui regras bem definidas para otimizar sua funcionalidade.<br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Chat moderado.</strong> </mark><mark style=\"background-color: rgba(0, 0, 0, 0);\"> </mark></p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p><mark style=\"background-color: rgba(0, 0, 0, 0);\">* Participação limitada a usuários que consigam entregar os jogos em Belo Horizonte</mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":45,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-resenha.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - RESENHA</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para a interação entre amantes de Boardgame. BG é o que nos une mas um bom papo fora do tema não é proibido. Novidades, jogatinas online, presenciais, dúvidas sobre regras, indicações. Aqui é o lugar. A única exigência é o bom senso.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem restrições</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":46,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-ofertas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - OFERTAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para divulgação de oportunidades e ofertas de Boardgames. Aqui é permitido a divulgação de anúncios em plataformas oficiais além de promoções em luderias e sites. Suas regras e funcionalidade ainda estão sendo definidas.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem chat</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%)\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"medium\"} -->\n<h2 style=\"color: #ffffff; font-style: normal; font-weight: 400;\">ENTRE EM CONTATO CONOSCO E SEJA UM APOIADOR OU PARCEIRO DO NOSSO PROJETO</h2>\n<!-- /wp:heading -->\n<!-- /wp:group -->		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>TORNEIOS REALIZADOS</h2>		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-widget-image-carousel .swiper,.elementor-widget-image-carousel .swiper-container{position:static}.elementor-widget-image-carousel .swiper-container .swiper-slide figure,.elementor-widget-image-carousel .swiper .swiper-slide figure{line-height:inherit}.elementor-widget-image-carousel .swiper-slide{text-align:center}.elementor-image-carousel-wrapper:not(.swiper-container-initialized):not(.swiper-initialized) .swiper-slide{max-width:calc(100% / var(--e-image-carousel-slides-to-show, 3))}</style>		\n								<figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne-300x161.png\" alt=\"torneio-carcassonne\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-300x161.png\" alt=\"torneio-draftosaurus\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel-300x161.png\" alt=\"torneio-7wduel\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express-300x161.png\" alt=\"torneio-colt-express\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur-300x161.png\" alt=\"torneio-jaipur\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale-300x161.png\" alt=\"torneio-forsale\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/desafio-sushigo-300x161.png\" alt=\"desafio-sushigo\" /></figure>', 'Home', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2023-12-23 08:17:54', '2023-12-23 11:17:54', '', 16, 'https://bgbh.com.br/blog/?p=526', 0, 'revision', '', 0),
(527, 1, '2023-12-23 08:17:54', '2023-12-23 11:17:54', '<link rel=\"stylesheet\" href=\"https://bgbh.com.br/blog/wp-content/plugins/elementor/assets/css/widget-icon-box.min.css\">		\n				<h3>\n						MATH TRADE BH					\n				</h3>\n									<p>\n						Organizamos a maior Math Trade regional do Brasil, a Math Trade BH					</p>\n				<h3>\n						Arena de Jogos					\n				</h3>\n									<p>\n						Estamos presente no maior evento geek de MG, o Nerd Experience, além de outros eventos Geek					</p>\n				<h3>\n						Grupos de discussão					\n				</h3>\n									<p>\n						Através da nossa \"Sala de Embarque\" tenha acesso a diversos grupos para interagir com a comunidade					</p>\n		<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\"}}},\"backgroundColor\":\"ast-global-color-5\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}}} -->\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":134,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<h2>NÃO FIQUE DE FORA</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaPosition\":\"right\",\"mediaId\":43,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=43\",\"linkDestination\":\"custom\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"imageFill\":false,\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"}},\"textColor\":\"ast-global-color-4\"} -->\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}},\"textColor\":\"ast-global-color-5\"} -->\n<h2 style=\"padding-right: 40px;\">NERD EXPERIENCE 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<figure><a href=\"https://nerdexperience.com.br/\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/326133700_189372070344481_5452170378878663579_n-1024x1024.jpeg\" alt=\"\" /></a></figure>\n<!-- /wp:media-text --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textColor\":\"ast-global-color-5\"} -->\n<h2>FIQUE LIGADO!</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaId\":59,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=59\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"}}} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/322515922_5441748755952564_4142625563983561065_n-1024x1024.jpeg\" alt=\"\" /></figure>\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}}} -->\n<h2 style=\"padding-right: 40px;\">COVIL CON 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<!-- /wp:media-text -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"wide\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>O QUE JÁ ACONTECEU</h2>\n<!-- /wp:heading --><!-- wp:heading {\"level\":3} -->\n<h3>Math Trade Belo Horizonte - Fevereiro 2023</h3>\n<!-- /wp:heading --><!-- wp:columns -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/o-que-e-uma-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Explicamos o que é <br />uma Math Trade</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Se não sabe o que é uma Math Trade, nós ajudamos. Temos uma página com explicações básicas do que é e como funciona uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":41,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/regras-gerais-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Conheça um pouco <br />mais das regras</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Agora que já sabe o que é, pode dar uma olhada na nossa página de regras gerais para se ambientar e estar pronto a participar de uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/615x330-MT-Fev23.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Math Trade BH <br />5a edição</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>No começo de Fevereiro de 2023 realizamos a 5a edição da Math Trade BH. Como sempre, um sucesso de cadastros e trocas.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns --><!-- wp:spacer {\"height\":\"40px\"} -->\n \n<!-- /wp:spacer --><!-- wp:heading {\"level\":3} -->\n<h3>NOSSOS TORNEIOS</h3>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"wide\",\"mediaId\":55,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=55\",\"mediaType\":\"image\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/Carcassonne-Banner-Web-1024x347.png\" alt=\"\" /></figure>\n<!-- wp:paragraph {\"placeholder\":\"Conteúdo...\"} -->\n<p><strong>ENCERRADO</strong></p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Em 2022 realizamos etapas regionais de Carcassonne, classificatórias para o nacional. Em 2023 teremos mais novidades</p>\n<!-- /wp:paragraph -->\n<!-- /wp:media-text --><!-- wp:paragraph -->\n<p>TORNEIOS REALIZADOS</p>\n<!-- /wp:paragraph --><!-- wp:gallery {\"columns\":6,\"linkTo\":\"none\",\"sizeSlug\":\"full\"} -->\n<figure><!-- wp:image {\"id\":56,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-1.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":52,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":47,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":48,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":49,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale.png\" alt=\"\" /></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery --><!-- wp:spacer {\"height\":\"0px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\"},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":false,\"contentSize\":\"800px\",\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":235,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/avatar.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"22px\",\"lineHeight\":1.6}},\"textColor\":\"ast-global-color-5\"} -->\n<p style=\"font-size: 22px; line-height: 1.6;\">“The best part is that Astra comes with hundreds of professionally designed templates for just about every industry, makes it super easy for non-techy users to build a website.”</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"ast-global-color-8\"} -->\n<p><strong>Wade Warren</strong></p>\n<!-- /wp:paragraph -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}}},\"textColor\":\"ast-global-color-4\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>NOSSOS GRUPOS</h2>\n<!-- /wp:heading --><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"80px\",\"margin\":{\"top\":\"60px\"}}}} -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":44,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-trocas-vendas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - TROCAS &amp; VENDAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">O grupo é <strong>EXCLUSIVO</strong> para Belo Horizonte e Região* e tem como foco os anúncios de trocas e vendas diretamente entre seus usuários. O grupo possui regras bem definidas para otimizar sua funcionalidade.<br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Chat moderado.</strong> </mark><mark style=\"background-color: rgba(0, 0, 0, 0);\"> </mark></p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p><mark style=\"background-color: rgba(0, 0, 0, 0);\">* Participação limitada a usuários que consigam entregar os jogos em Belo Horizonte</mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":45,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-resenha.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - RESENHA</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para a interação entre amantes de Boardgame. BG é o que nos une mas um bom papo fora do tema não é proibido. Novidades, jogatinas online, presenciais, dúvidas sobre regras, indicações. Aqui é o lugar. A única exigência é o bom senso.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem restrições</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":46,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-ofertas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - OFERTAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para divulgação de oportunidades e ofertas de Boardgames. Aqui é permitido a divulgação de anúncios em plataformas oficiais além de promoções em luderias e sites. Suas regras e funcionalidade ainda estão sendo definidas.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem chat</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%)\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"medium\"} -->\n<h2 style=\"color: #ffffff; font-style: normal; font-weight: 400;\">ENTRE EM CONTATO CONOSCO E SEJA UM APOIADOR OU PARCEIRO DO NOSSO PROJETO</h2>\n<!-- /wp:heading -->\n<!-- /wp:group -->		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>TORNEIOS REALIZADOS</h2>		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-widget-image-carousel .swiper,.elementor-widget-image-carousel .swiper-container{position:static}.elementor-widget-image-carousel .swiper-container .swiper-slide figure,.elementor-widget-image-carousel .swiper .swiper-slide figure{line-height:inherit}.elementor-widget-image-carousel .swiper-slide{text-align:center}.elementor-image-carousel-wrapper:not(.swiper-container-initialized):not(.swiper-initialized) .swiper-slide{max-width:calc(100% / var(--e-image-carousel-slides-to-show, 3))}</style>		\n								<figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne-300x161.png\" alt=\"torneio-carcassonne\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-300x161.png\" alt=\"torneio-draftosaurus\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel-300x161.png\" alt=\"torneio-7wduel\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express-300x161.png\" alt=\"torneio-colt-express\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur-300x161.png\" alt=\"torneio-jaipur\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale-300x161.png\" alt=\"torneio-forsale\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/desafio-sushigo-300x161.png\" alt=\"desafio-sushigo\" /></figure>', 'Home', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2023-12-23 08:17:54', '2023-12-23 11:17:54', '', 16, 'https://bgbh.com.br/blog/?p=527', 0, 'revision', '', 0);
INSERT INTO `wptask_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(528, 1, '2023-12-23 08:17:54', '2023-12-23 11:17:54', '<link rel=\"stylesheet\" href=\"https://bgbh.com.br/blog/wp-content/plugins/elementor/assets/css/widget-icon-box.min.css\">		\n				<h3>\n						MATH TRADE BH					\n				</h3>\n									<p>\n						Organizamos a maior Math Trade regional do Brasil, a Math Trade BH					</p>\n				<h3>\n						Arena de Jogos					\n				</h3>\n									<p>\n						Estamos presente no maior evento geek de MG, o Nerd Experience, além de outros eventos Geek					</p>\n				<h3>\n						Grupos de discussão					\n				</h3>\n									<p>\n						Através da nossa \"Sala de Embarque\" tenha acesso a diversos grupos para interagir com a comunidade					</p>\n		<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\"}}},\"backgroundColor\":\"ast-global-color-5\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}}} -->\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":134,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<h2>NÃO FIQUE DE FORA</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaPosition\":\"right\",\"mediaId\":43,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=43\",\"linkDestination\":\"custom\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"imageFill\":false,\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"}},\"textColor\":\"ast-global-color-4\"} -->\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}},\"textColor\":\"ast-global-color-5\"} -->\n<h2 style=\"padding-right: 40px;\">NERD EXPERIENCE 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<figure><a href=\"https://nerdexperience.com.br/\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/326133700_189372070344481_5452170378878663579_n-1024x1024.jpeg\" alt=\"\" /></a></figure>\n<!-- /wp:media-text --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textColor\":\"ast-global-color-5\"} -->\n<h2>FIQUE LIGADO!</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaId\":59,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=59\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"}}} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/322515922_5441748755952564_4142625563983561065_n-1024x1024.jpeg\" alt=\"\" /></figure>\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}}} -->\n<h2 style=\"padding-right: 40px;\">COVIL CON 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<!-- /wp:media-text -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"wide\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>O QUE JÁ ACONTECEU</h2>\n<!-- /wp:heading --><!-- wp:heading {\"level\":3} -->\n<h3>Math Trade Belo Horizonte - Fevereiro 2023</h3>\n<!-- /wp:heading --><!-- wp:columns -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/o-que-e-uma-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Explicamos o que é <br />uma Math Trade</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Se não sabe o que é uma Math Trade, nós ajudamos. Temos uma página com explicações básicas do que é e como funciona uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":41,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/regras-gerais-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Conheça um pouco <br />mais das regras</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Agora que já sabe o que é, pode dar uma olhada na nossa página de regras gerais para se ambientar e estar pronto a participar de uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/615x330-MT-Fev23.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Math Trade BH <br />5a edição</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>No começo de Fevereiro de 2023 realizamos a 5a edição da Math Trade BH. Como sempre, um sucesso de cadastros e trocas.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns --><!-- wp:spacer {\"height\":\"40px\"} -->\n \n<!-- /wp:spacer --><!-- wp:heading {\"level\":3} -->\n<h3>NOSSOS TORNEIOS</h3>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"wide\",\"mediaId\":55,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=55\",\"mediaType\":\"image\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/Carcassonne-Banner-Web-1024x347.png\" alt=\"\" /></figure>\n<!-- wp:paragraph {\"placeholder\":\"Conteúdo...\"} -->\n<p><strong>ENCERRADO</strong></p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Em 2022 realizamos etapas regionais de Carcassonne, classificatórias para o nacional. Em 2023 teremos mais novidades</p>\n<!-- /wp:paragraph -->\n<!-- /wp:media-text --><!-- wp:paragraph -->\n<p>TORNEIOS REALIZADOS</p>\n<!-- /wp:paragraph --><!-- wp:gallery {\"columns\":6,\"linkTo\":\"none\",\"sizeSlug\":\"full\"} -->\n<figure><!-- wp:image {\"id\":56,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-1.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":52,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":47,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":48,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":49,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale.png\" alt=\"\" /></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery --><!-- wp:spacer {\"height\":\"0px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\"},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":false,\"contentSize\":\"800px\",\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":235,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/avatar.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"22px\",\"lineHeight\":1.6}},\"textColor\":\"ast-global-color-5\"} -->\n<p style=\"font-size: 22px; line-height: 1.6;\">“The best part is that Astra comes with hundreds of professionally designed templates for just about every industry, makes it super easy for non-techy users to build a website.”</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"ast-global-color-8\"} -->\n<p><strong>Wade Warren</strong></p>\n<!-- /wp:paragraph -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}}},\"textColor\":\"ast-global-color-4\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>NOSSOS GRUPOS</h2>\n<!-- /wp:heading --><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"80px\",\"margin\":{\"top\":\"60px\"}}}} -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":44,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-trocas-vendas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - TROCAS &amp; VENDAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">O grupo é <strong>EXCLUSIVO</strong> para Belo Horizonte e Região* e tem como foco os anúncios de trocas e vendas diretamente entre seus usuários. O grupo possui regras bem definidas para otimizar sua funcionalidade.<br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Chat moderado.</strong> </mark><mark style=\"background-color: rgba(0, 0, 0, 0);\"> </mark></p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p><mark style=\"background-color: rgba(0, 0, 0, 0);\">* Participação limitada a usuários que consigam entregar os jogos em Belo Horizonte</mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":45,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-resenha.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - RESENHA</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para a interação entre amantes de Boardgame. BG é o que nos une mas um bom papo fora do tema não é proibido. Novidades, jogatinas online, presenciais, dúvidas sobre regras, indicações. Aqui é o lugar. A única exigência é o bom senso.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem restrições</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":46,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-ofertas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - OFERTAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para divulgação de oportunidades e ofertas de Boardgames. Aqui é permitido a divulgação de anúncios em plataformas oficiais além de promoções em luderias e sites. Suas regras e funcionalidade ainda estão sendo definidas.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem chat</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%)\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"medium\"} -->\n<h2 style=\"color: #ffffff; font-style: normal; font-weight: 400;\">ENTRE EM CONTATO CONOSCO E SEJA UM APOIADOR OU PARCEIRO DO NOSSO PROJETO</h2>\n<!-- /wp:heading -->\n<!-- /wp:group -->		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-column .elementor-spacer-inner{height:var(--spacer-size)}.e-con{--container-widget-width:100%}.e-con-inner>.elementor-widget-spacer,.e-con>.elementor-widget-spacer{width:var(--container-widget-width,var(--spacer-size));--align-self:var(--container-widget-align-self,initial);--flex-shrink:0}.e-con-inner>.elementor-widget-spacer>.elementor-widget-container,.e-con>.elementor-widget-spacer>.elementor-widget-container{height:100%;width:100%}.e-con-inner>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer,.e-con>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer{height:100%}.e-con-inner>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer>.elementor-spacer-inner,.e-con>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer>.elementor-spacer-inner{height:var(--container-widget-height,var(--spacer-size))}.e-con-inner>.elementor-widget-spacer.elementor-widget-empty,.e-con>.elementor-widget-spacer.elementor-widget-empty{position:relative;min-height:22px;min-width:22px}.e-con-inner>.elementor-widget-spacer.elementor-widget-empty .elementor-widget-empty-icon,.e-con>.elementor-widget-spacer.elementor-widget-empty .elementor-widget-empty-icon{position:absolute;top:0;bottom:0;left:0;right:0;margin:auto;padding:0;width:22px;height:22px}</style>		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>TORNEIOS REALIZADOS</h2>		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-widget-image-carousel .swiper,.elementor-widget-image-carousel .swiper-container{position:static}.elementor-widget-image-carousel .swiper-container .swiper-slide figure,.elementor-widget-image-carousel .swiper .swiper-slide figure{line-height:inherit}.elementor-widget-image-carousel .swiper-slide{text-align:center}.elementor-image-carousel-wrapper:not(.swiper-container-initialized):not(.swiper-initialized) .swiper-slide{max-width:calc(100% / var(--e-image-carousel-slides-to-show, 3))}</style>		\n								<figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne-300x161.png\" alt=\"torneio-carcassonne\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-300x161.png\" alt=\"torneio-draftosaurus\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel-300x161.png\" alt=\"torneio-7wduel\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express-300x161.png\" alt=\"torneio-colt-express\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur-300x161.png\" alt=\"torneio-jaipur\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale-300x161.png\" alt=\"torneio-forsale\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/desafio-sushigo-300x161.png\" alt=\"desafio-sushigo\" /></figure>', 'Home', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2023-12-23 08:17:54', '2023-12-23 11:17:54', '', 16, 'https://bgbh.com.br/blog/?p=528', 0, 'revision', '', 0),
(530, 1, '2023-12-23 08:26:53', '2023-12-23 11:26:53', '<link rel=\"stylesheet\" href=\"https://bgbh.com.br/blog/wp-content/plugins/elementor/assets/css/widget-icon-box.min.css\">		\n				<h3>\n						MATH TRADE BH					\n				</h3>\n									<p>\n						Organizamos a maior Math Trade regional do Brasil, a Math Trade BH					</p>\n				<h3>\n						Arena de Jogos					\n				</h3>\n									<p>\n						Estamos presente no maior evento geek de MG, o Nerd Experience, além de outros eventos Geek					</p>\n				<h3>\n						Grupos de discussão					\n				</h3>\n									<p>\n						Através da nossa \"Sala de Embarque\" tenha acesso a diversos grupos para interagir com a comunidade					</p>\n		<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\"}}},\"backgroundColor\":\"ast-global-color-5\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}}} -->\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":134,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<h2>NÃO FIQUE DE FORA</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaPosition\":\"right\",\"mediaId\":43,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=43\",\"linkDestination\":\"custom\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"imageFill\":false,\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"}},\"textColor\":\"ast-global-color-4\"} -->\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}},\"textColor\":\"ast-global-color-5\"} -->\n<h2 style=\"padding-right: 40px;\">NERD EXPERIENCE 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<figure><a href=\"https://nerdexperience.com.br/\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/326133700_189372070344481_5452170378878663579_n-1024x1024.jpeg\" alt=\"\" /></a></figure>\n<!-- /wp:media-text --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textColor\":\"ast-global-color-5\"} -->\n<h2>FIQUE LIGADO!</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaId\":59,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=59\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"}}} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/322515922_5441748755952564_4142625563983561065_n-1024x1024.jpeg\" alt=\"\" /></figure>\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}}} -->\n<h2 style=\"padding-right: 40px;\">COVIL CON 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<!-- /wp:media-text -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"wide\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>O QUE JÁ ACONTECEU</h2>\n<!-- /wp:heading --><!-- wp:heading {\"level\":3} -->\n<h3>Math Trade Belo Horizonte - Fevereiro 2023</h3>\n<!-- /wp:heading --><!-- wp:columns -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/o-que-e-uma-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Explicamos o que é <br />uma Math Trade</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Se não sabe o que é uma Math Trade, nós ajudamos. Temos uma página com explicações básicas do que é e como funciona uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":41,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/regras-gerais-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Conheça um pouco <br />mais das regras</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Agora que já sabe o que é, pode dar uma olhada na nossa página de regras gerais para se ambientar e estar pronto a participar de uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/615x330-MT-Fev23.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Math Trade BH <br />5a edição</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>No começo de Fevereiro de 2023 realizamos a 5a edição da Math Trade BH. Como sempre, um sucesso de cadastros e trocas.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns --><!-- wp:spacer {\"height\":\"40px\"} -->\n \n<!-- /wp:spacer --><!-- wp:heading {\"level\":3} -->\n<h3>NOSSOS TORNEIOS</h3>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"wide\",\"mediaId\":55,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=55\",\"mediaType\":\"image\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/Carcassonne-Banner-Web-1024x347.png\" alt=\"\" /></figure>\n<!-- wp:paragraph {\"placeholder\":\"Conteúdo...\"} -->\n<p><strong>ENCERRADO</strong></p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Em 2022 realizamos etapas regionais de Carcassonne, classificatórias para o nacional. Em 2023 teremos mais novidades</p>\n<!-- /wp:paragraph -->\n<!-- /wp:media-text --><!-- wp:paragraph -->\n<p>TORNEIOS REALIZADOS</p>\n<!-- /wp:paragraph --><!-- wp:gallery {\"columns\":6,\"linkTo\":\"none\",\"sizeSlug\":\"full\"} -->\n<figure><!-- wp:image {\"id\":56,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-1.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":52,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":47,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":48,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":49,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale.png\" alt=\"\" /></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery --><!-- wp:spacer {\"height\":\"0px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\"},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":false,\"contentSize\":\"800px\",\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":235,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/avatar.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"22px\",\"lineHeight\":1.6}},\"textColor\":\"ast-global-color-5\"} -->\n<p style=\"font-size: 22px; line-height: 1.6;\">“The best part is that Astra comes with hundreds of professionally designed templates for just about every industry, makes it super easy for non-techy users to build a website.”</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"ast-global-color-8\"} -->\n<p><strong>Wade Warren</strong></p>\n<!-- /wp:paragraph -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}}},\"textColor\":\"ast-global-color-4\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>NOSSOS GRUPOS</h2>\n<!-- /wp:heading --><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"80px\",\"margin\":{\"top\":\"60px\"}}}} -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":44,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-trocas-vendas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - TROCAS &amp; VENDAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">O grupo é <strong>EXCLUSIVO</strong> para Belo Horizonte e Região* e tem como foco os anúncios de trocas e vendas diretamente entre seus usuários. O grupo possui regras bem definidas para otimizar sua funcionalidade.<br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Chat moderado.</strong> </mark><mark style=\"background-color: rgba(0, 0, 0, 0);\"> </mark></p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p><mark style=\"background-color: rgba(0, 0, 0, 0);\">* Participação limitada a usuários que consigam entregar os jogos em Belo Horizonte</mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":45,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-resenha.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - RESENHA</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para a interação entre amantes de Boardgame. BG é o que nos une mas um bom papo fora do tema não é proibido. Novidades, jogatinas online, presenciais, dúvidas sobre regras, indicações. Aqui é o lugar. A única exigência é o bom senso.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem restrições</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":46,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-ofertas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - OFERTAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para divulgação de oportunidades e ofertas de Boardgames. Aqui é permitido a divulgação de anúncios em plataformas oficiais além de promoções em luderias e sites. Suas regras e funcionalidade ainda estão sendo definidas.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem chat</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%)\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"medium\"} -->\n<h2 style=\"color: #ffffff; font-style: normal; font-weight: 400;\">ENTRE EM CONTATO CONOSCO E SEJA UM APOIADOR OU PARCEIRO DO NOSSO PROJETO</h2>\n<!-- /wp:heading -->\n<!-- /wp:group -->		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-column .elementor-spacer-inner{height:var(--spacer-size)}.e-con{--container-widget-width:100%}.e-con-inner>.elementor-widget-spacer,.e-con>.elementor-widget-spacer{width:var(--container-widget-width,var(--spacer-size));--align-self:var(--container-widget-align-self,initial);--flex-shrink:0}.e-con-inner>.elementor-widget-spacer>.elementor-widget-container,.e-con>.elementor-widget-spacer>.elementor-widget-container{height:100%;width:100%}.e-con-inner>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer,.e-con>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer{height:100%}.e-con-inner>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer>.elementor-spacer-inner,.e-con>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer>.elementor-spacer-inner{height:var(--container-widget-height,var(--spacer-size))}.e-con-inner>.elementor-widget-spacer.elementor-widget-empty,.e-con>.elementor-widget-spacer.elementor-widget-empty{position:relative;min-height:22px;min-width:22px}.e-con-inner>.elementor-widget-spacer.elementor-widget-empty .elementor-widget-empty-icon,.e-con>.elementor-widget-spacer.elementor-widget-empty .elementor-widget-empty-icon{position:absolute;top:0;bottom:0;left:0;right:0;margin:auto;padding:0;width:22px;height:22px}</style>		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>TORNEIOS REALIZADOS</h2>		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-widget-image-carousel .swiper,.elementor-widget-image-carousel .swiper-container{position:static}.elementor-widget-image-carousel .swiper-container .swiper-slide figure,.elementor-widget-image-carousel .swiper .swiper-slide figure{line-height:inherit}.elementor-widget-image-carousel .swiper-slide{text-align:center}.elementor-image-carousel-wrapper:not(.swiper-container-initialized):not(.swiper-initialized) .swiper-slide{max-width:calc(100% / var(--e-image-carousel-slides-to-show, 3))}</style>		\n								<figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne-300x161.png\" alt=\"torneio-carcassonne\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-300x161.png\" alt=\"torneio-draftosaurus\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel-300x161.png\" alt=\"torneio-7wduel\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express-300x161.png\" alt=\"torneio-colt-express\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur-300x161.png\" alt=\"torneio-jaipur\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale-300x161.png\" alt=\"torneio-forsale\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/desafio-sushigo-300x161.png\" alt=\"desafio-sushigo\" /></figure>', 'Home', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2023-12-23 08:26:53', '2023-12-23 11:26:53', '', 16, 'https://bgbh.com.br/blog/?p=530', 0, 'revision', '', 0);
INSERT INTO `wptask_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(531, 1, '2023-12-23 08:26:53', '2023-12-23 11:26:53', '<link rel=\"stylesheet\" href=\"https://bgbh.com.br/blog/wp-content/plugins/elementor/assets/css/widget-icon-box.min.css\">		\n				<h3>\n						MATH TRADE BH					\n				</h3>\n									<p>\n						Organizamos a maior Math Trade regional do Brasil, a Math Trade BH					</p>\n				<h3>\n						Arena de Jogos					\n				</h3>\n									<p>\n						Estamos presente no maior evento geek de MG, o Nerd Experience, além de outros eventos Geek					</p>\n				<h3>\n						Grupos de discussão					\n				</h3>\n									<p>\n						Através da nossa \"Sala de Embarque\" tenha acesso a diversos grupos para interagir com a comunidade					</p>\n		<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\"}}},\"backgroundColor\":\"ast-global-color-5\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}}} -->\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":134,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<h2>NÃO FIQUE DE FORA</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaPosition\":\"right\",\"mediaId\":43,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=43\",\"linkDestination\":\"custom\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"imageFill\":false,\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(120,200,205) 0%,rgb(93,36,129) 99%)\"}},\"textColor\":\"ast-global-color-4\"} -->\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}},\"textColor\":\"ast-global-color-5\"} -->\n<h2 style=\"padding-right: 40px;\">NERD EXPERIENCE 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"textColor\":\"ast-global-color-5\"} -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<figure><a href=\"https://nerdexperience.com.br/\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/326133700_189372070344481_5452170378878663579_n-1024x1024.jpeg\" alt=\"\" /></a></figure>\n<!-- /wp:media-text --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 53%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textColor\":\"ast-global-color-5\"} -->\n<h2>FIQUE LIGADO!</h2>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"\",\"mediaId\":59,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=59\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(250,149,0) 0%,rgb(203,75,13) 100%)\"}}} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/322515922_5441748755952564_4142625563983561065_n-1024x1024.jpeg\" alt=\"\" /></figure>\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"80px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"style\":{\"spacing\":{\"padding\":{\"right\":\"40px\"}}}} -->\n<h2 style=\"padding-right: 40px;\">COVIL CON 2023</h2>\n<!-- /wp:heading --><!-- wp:paragraph -->\n<p>Et in risus egestas nec vitae odio ac nibh vestibulum volutpat aliquet aenean erat lobortis non.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Nibh egestas dictumst cursus est turpis quis tincidunt pulvinar maecenas eget massa vel, ante nam blandit egestas enim id quis sit maecenas id nunc tempus auctor orci, enim imperdiet proin nibh mattis.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<!-- /wp:media-text -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"wide\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>O QUE JÁ ACONTECEU</h2>\n<!-- /wp:heading --><!-- wp:heading {\"level\":3} -->\n<h3>Math Trade Belo Horizonte - Fevereiro 2023</h3>\n<!-- /wp:heading --><!-- wp:columns -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/o-que-e-uma-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Explicamos o que é <br />uma Math Trade</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Se não sabe o que é uma Math Trade, nós ajudamos. Temos uma página com explicações básicas do que é e como funciona uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":41,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/regras-gerais-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Conheça um pouco <br />mais das regras</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Agora que já sabe o que é, pode dar uma olhada na nossa página de regras gerais para se ambientar e estar pronto a participar de uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/615x330-MT-Fev23.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Math Trade BH <br />5a edição</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>No começo de Fevereiro de 2023 realizamos a 5a edição da Math Trade BH. Como sempre, um sucesso de cadastros e trocas.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns --><!-- wp:spacer {\"height\":\"40px\"} -->\n \n<!-- /wp:spacer --><!-- wp:heading {\"level\":3} -->\n<h3>NOSSOS TORNEIOS</h3>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"wide\",\"mediaId\":55,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=55\",\"mediaType\":\"image\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/Carcassonne-Banner-Web-1024x347.png\" alt=\"\" /></figure>\n<!-- wp:paragraph {\"placeholder\":\"Conteúdo...\"} -->\n<p><strong>ENCERRADO</strong></p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Em 2022 realizamos etapas regionais de Carcassonne, classificatórias para o nacional. Em 2023 teremos mais novidades</p>\n<!-- /wp:paragraph -->\n<!-- /wp:media-text --><!-- wp:paragraph -->\n<p>TORNEIOS REALIZADOS</p>\n<!-- /wp:paragraph --><!-- wp:gallery {\"columns\":6,\"linkTo\":\"none\",\"sizeSlug\":\"full\"} -->\n<figure><!-- wp:image {\"id\":56,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-1.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":52,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":47,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":48,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:image {\"id\":49,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale.png\" alt=\"\" /></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery --><!-- wp:spacer {\"height\":\"0px\"} -->\n \n<!-- /wp:spacer -->\n<!-- /wp:group --><!-- wp:spacer {\"height\":\"60px\"} -->\n \n<!-- /wp:spacer --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\"},\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 52%,rgb(64,66,72) 100%)\"}},\"layout\":{\"inherit\":false,\"contentSize\":\"800px\",\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":235,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/themes/astra/inc/assets/images/starter-content/avatar.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"22px\",\"lineHeight\":1.6}},\"textColor\":\"ast-global-color-5\"} -->\n<p style=\"font-size: 22px; line-height: 1.6;\">“The best part is that Astra comes with hundreds of professionally designed templates for just about every industry, makes it super easy for non-techy users to build a website.”</p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"ast-global-color-8\"} -->\n<p><strong>Wade Warren</strong></p>\n<!-- /wp:paragraph -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"60px\",\"bottom\":\"60px\"}}},\"textColor\":\"ast-global-color-4\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>NOSSOS GRUPOS</h2>\n<!-- /wp:heading --><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"80px\",\"margin\":{\"top\":\"60px\"}}}} -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":44,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-trocas-vendas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - TROCAS &amp; VENDAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">O grupo é <strong>EXCLUSIVO</strong> para Belo Horizonte e Região* e tem como foco os anúncios de trocas e vendas diretamente entre seus usuários. O grupo possui regras bem definidas para otimizar sua funcionalidade.<br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Chat moderado.</strong> </mark><mark style=\"background-color: rgba(0, 0, 0, 0);\"> </mark></p>\n<!-- /wp:paragraph --><!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p><mark style=\"background-color: rgba(0, 0, 0, 0);\">* Participação limitada a usuários que consigam entregar os jogos em Belo Horizonte</mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":45,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-resenha.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - RESENHA</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para a interação entre amantes de Boardgame. BG é o que nos une mas um bom papo fora do tema não é proibido. Novidades, jogatinas online, presenciais, dúvidas sobre regras, indicações. Aqui é o lugar. A única exigência é o bom senso.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem restrições</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":46,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/grupo-wpp-ofertas.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">BGBH - OFERTAS</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#404248\"}}} -->\n<p style=\"color: #404248;\">Grupo voltado para divulgação de oportunidades e ofertas de Boardgames. Aqui é permitido a divulgação de anúncios em plataformas oficiais além de promoções em luderias e sites. Suas regras e funcionalidade ainda estão sendo definidas.<br /><br /><mark style=\"background-color: rgba(0, 0, 0, 0);\"><strong>Restrições: Sem chat</strong></mark></p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns -->\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"gradient\":\"radial-gradient(rgb(25,135,84) 0%,rgb(19,108,67) 64%,rgb(64,66,72) 98%)\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"medium\"} -->\n<h2 style=\"color: #ffffff; font-style: normal; font-weight: 400;\">ENTRE EM CONTATO CONOSCO E SEJA UM APOIADOR OU PARCEIRO DO NOSSO PROJETO</h2>\n<!-- /wp:heading -->\n<!-- /wp:group -->		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-column .elementor-spacer-inner{height:var(--spacer-size)}.e-con{--container-widget-width:100%}.e-con-inner>.elementor-widget-spacer,.e-con>.elementor-widget-spacer{width:var(--container-widget-width,var(--spacer-size));--align-self:var(--container-widget-align-self,initial);--flex-shrink:0}.e-con-inner>.elementor-widget-spacer>.elementor-widget-container,.e-con>.elementor-widget-spacer>.elementor-widget-container{height:100%;width:100%}.e-con-inner>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer,.e-con>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer{height:100%}.e-con-inner>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer>.elementor-spacer-inner,.e-con>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer>.elementor-spacer-inner{height:var(--container-widget-height,var(--spacer-size))}.e-con-inner>.elementor-widget-spacer.elementor-widget-empty,.e-con>.elementor-widget-spacer.elementor-widget-empty{position:relative;min-height:22px;min-width:22px}.e-con-inner>.elementor-widget-spacer.elementor-widget-empty .elementor-widget-empty-icon,.e-con>.elementor-widget-spacer.elementor-widget-empty .elementor-widget-empty-icon{position:absolute;top:0;bottom:0;left:0;right:0;margin:auto;padding:0;width:22px;height:22px}</style>		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>TORNEIOS REALIZADOS</h2>		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-widget-image-carousel .swiper,.elementor-widget-image-carousel .swiper-container{position:static}.elementor-widget-image-carousel .swiper-container .swiper-slide figure,.elementor-widget-image-carousel .swiper .swiper-slide figure{line-height:inherit}.elementor-widget-image-carousel .swiper-slide{text-align:center}.elementor-image-carousel-wrapper:not(.swiper-container-initialized):not(.swiper-initialized) .swiper-slide{max-width:calc(100% / var(--e-image-carousel-slides-to-show, 3))}</style>		\n								<figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-carcassonne-300x161.png\" alt=\"torneio-carcassonne\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-draftosaurus-300x161.png\" alt=\"torneio-draftosaurus\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-7wduel-300x161.png\" alt=\"torneio-7wduel\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-colt-express-300x161.png\" alt=\"torneio-colt-express\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-jaipur-300x161.png\" alt=\"torneio-jaipur\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/torneio-forsale-300x161.png\" alt=\"torneio-forsale\" /></figure><figure><img data-src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/desafio-sushigo-300x161.png\" alt=\"desafio-sushigo\" /></figure>', 'Home', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2023-12-23 08:26:53', '2023-12-23 11:26:53', '', 16, 'https://bgbh.com.br/blog/?p=531', 0, 'revision', '', 0),
(532, 1, '2023-12-23 08:26:54', '2023-12-23 11:26:54', '<link rel=\"stylesheet\" href=\"https://bgbh.com.br/blog/wp-content/plugins/elementor/assets/css/widget-icon-box.min.css\">		\n				<h3>\n						MATH TRADE BH					\n				</h3>\n									<p>\n						Organizamos a maior Math Trade regional do Brasil, a Math Trade BH					</p>\n				<h3>\n						Arena de Jogos					\n				</h3>\n									<p>\n						Estamos presente no maior evento geek de MG, o Nerd Experience, além de outros eventos Geek					</p>\n				<h3>\n						Grupos de discussão					\n				</h3>\n									<p>\n						Através da nossa \"Sala de Embarque\" tenha acesso a diversos grupos para interagir com a comunidade					</p>\n		<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"0px\"}}},\"backgroundColor\":\"ast-global-color-5\",\"layout\":{\"inherit\":false,\"contentSize\":\"1200px\",\"type\":\"constrained\"}} -->\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}}} -->\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"align\":\"center\",\"id\":134,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n \nO QUE JÁ ACONTECEU\n<!-- /wp:heading --><!-- wp:heading {\"level\":3} -->\n<h3>Math Trade Belo Horizonte - Fevereiro 2023</h3>\n<!-- /wp:heading --><!-- wp:columns -->\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/o-que-e-uma-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Explicamos o que é <br />uma Math Trade</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Se não sabe o que é uma Math Trade, nós ajudamos. Temos uma página com explicações básicas do que é e como funciona uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":41,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/regras-gerais-math-trade.jpeg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Conheça um pouco <br />mais das regras</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>Agora que já sabe o que é, pode dar uma olhada na nossa página de regras gerais para se ambientar e estar pronto a participar de uma Math Trade.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column --><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/615x330-MT-Fev23.png\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h4 style=\"margin-top: 16px;\">Math Trade BH <br />5a edição</h4>\n<!-- /wp:heading --><!-- wp:paragraph {\"align\":\"center\"} -->\n<p>No começo de Fevereiro de 2023 realizamos a 5a edição da Math Trade BH. Como sempre, um sucesso de cadastros e trocas.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:column -->\n<!-- /wp:columns --><!-- wp:spacer {\"height\":\"40px\"} -->\n \n<!-- /wp:spacer --><!-- wp:heading {\"level\":3} -->\n<h3>NOSSOS TORNEIOS</h3>\n<!-- /wp:heading --><!-- wp:media-text {\"align\":\"wide\",\"mediaId\":55,\"mediaLink\":\"https://bgbh.com.br/blog/?attachment_id=55\",\"mediaType\":\"image\"} -->\n<figure><img src=\"https://bgbh.com.br/blog/wp-content/uploads/2023/01/Carcassonne-Banner-Web-1024x347.png\" alt=\"\" /></figure>\n<!-- wp:paragraph {\"placeholder\":\"Conteúdo...\"} -->\n<p><strong>ENCERRADO</strong></p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>Em 2022 realizamos etapas regionais de Carcassonne, classificatórias para o nacional. Em 2023 teremos mais novidades</p>\n<!-- /wp:group -->		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>ENTRE EM CONTATO CONOSCO E SEJA UM APOIADOR OU PARCEIRO DO NOSSO PROJETO</h2>		\n			<style>/*! elementor - v3.18.0 - 20-12-2023 */\n.elementor-column .elementor-spacer-inner{height:var(--spacer-size)}.e-con{--container-widget-width:100%}.e-con-inner>.elementor-widget-spacer,.e-con>.elementor-widget-spacer{width:var(--container-widget-width,var(--spacer-size));--align-self:var(--container-widget-align-self,initial);--flex-shrink:0}.e-con-inner>.elementor-widget-spacer>.elementor-widget-container,.e-con>.elementor-widget-spacer>.elementor-widget-container{height:100%;width:100%}.e-con-inner>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer,.e-con>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer{height:100%}.e-con-inner>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer>.elementor-spacer-inner,.e-con>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer>.elementor-spacer-inner{height:var(--container-widget-height,var(--spacer-s